// radio_golden_2025_aug_evening.js — Radiology 4 August Evening 2025 paper (199 source MCQs, #199 ignored per user instruction = 198 total)
// Schema: {q,o,a,e} with 5 options A-E and answer index 0-4
// Explanation: P1 mechanism + Take Notes discriminator chain (target ~50 words total)
if(!window.MM) window.MM={};
window.MM['radio_golden_2025_aug_evening']=[
/*1*/ {"q":"A 15-year-old girl is brought to the clinic for evaluation of short stature and delayed puberty. She has never menstruated and has minimal breast development. Karyotyping is ordered. Which of the following is the most likely chromosomal abnormality for the phenotype of Turner's syndrome?","o":["Monosomy of X","Monosomy of Y","Trisomy 21","47, XXX","Non-disjunction of chromosome 21"],"a":0,"e":"Turner syndrome (45,X): primary amenorrhea, short stature, webbed neck, lymphedema, streak ovaries, cardiac defects. Single X chromosome (monosomy X) is the karyotypic basis.<br><br>Take Notes: Trisomy 21 → Down syndrome | 47,XXX → triple X (mild) | Turner phenotype = monosomy X (45,X)."},
/*2*/ {"q":"A 34-year-old man presents after a laceration to his hand from broken glass. He is unable to bring his thumb towards his palm when attempting to grasp objects. Physical examination reveals weakness in adduction of the thumb. Which nerve is most likely injured?","o":["Ulnar nerve","Median nerve","Radial nerve","Musculocutaneous nerve","Posterior cord of brachial plexus"],"a":0,"e":"Thumb adduction is performed by adductor pollicis muscle, supplied by deep branch of ulnar nerve. Ulnar nerve injury (e.g., wrist laceration) causes thumb adduction weakness and impaired pinch grip (Froment sign).<br><br>Take Notes: Median → thenar opposition (LOAF) | Radial → wrist extension | Thumb adduction loss = ulnar nerve."},
/*3*/ {"q":"A 52-year-old man with a history of recurrent urinary tract infections is prescribed ciprofloxacin. Which of the following best describes the mechanism of action of this drug?","o":["Inhibition of dihydropteroate synthase","Inhibition of DNA gyrase and topoisomerase IV","Binding to the 50S ribosomal subunit","Inhibition of transpeptidase enzyme","Inhibits 30S unit of the ribosome"],"a":1,"e":"Ciprofloxacin (fluoroquinolone) inhibits bacterial DNA gyrase (topoisomerase II) and topoisomerase IV, preventing DNA replication. Active against gram-negative organisms including E. coli, Pseudomonas.<br><br>Take Notes: Sulfonamides → dihydropteroate synthase | Macrolides → 50S ribosome | β-lactams → transpeptidase | Ciprofloxacin = DNA gyrase + topo IV."},
/*4*/ {"q":"A 27-year-old man sustains a stab wound just to the right and inferior to the xiphisternum at the level of the 6th costal cartilage. Which of the following cardiac or great vessel structures is most likely to be injured?","o":["Right atrium","Left atrium","Left ventricle","Ascending aorta","Left pulmonary vein"],"a":0,"e":"Right atrium occupies the right cardiac border from 3rd to 6th costal cartilage; a stab at right of xiphisternum at 6th costal cartilage most likely injures the right atrium directly.<br><br>Take Notes: Left ventricle → forms apex | Aorta → midline | Right side at 6th costal cartilage = right atrium."},
/*5*/ {"q":"A 25-year-old man presents after a bicycle accident in which the handlebars struck his pelvis. He has pain over the pubic region and difficulty walking. Imaging reveals a fracture of the symphysis pubis. Which of the following structures is most likely to be injured?","o":["Urinary bladder","Prostate gland","Femoral artery","External iliac vein","Levator ani"],"a":0,"e":"Pelvic fractures involving pubic symphysis can lacerate the urinary bladder (especially full bladder) due to its retropubic location. Suprapubic pain and difficulty voiding suggest bladder injury.<br><br>Take Notes: Prostate → posterior to symphysis (less risky) | Femoral artery → lateral | Pubic symphysis fracture = bladder injury."},
/*6*/ {"q":"A researcher is studying the normal distribution of lymphocyte subpopulations in peripheral blood. Which of the following percentages most closely represents the proportion of lymphocytes in healthy individuals?","o":["B cells 10-20%","B cells 20-40%","T cells 60-70%","T cells 80-90%","Both B and T cells 50% each"],"a":3,"e":"In healthy individuals, T lymphocytes comprise 60-80% of circulating lymphocytes, B cells 10-20%, NK cells 5-10%. T cell predominance reflects extensive thymic processing and adaptive immunity importance.<br><br>Take Notes: B cells → 10-20% | NK cells → 5-10% | T cells = 60-80% (predominant)."},
/*7*/ {"q":"A 54-year-old woman with a history of breast cancer presents with progressive back pain. MRI reveals metastases to vertebral bodies. Which of the following is the most likely route of spread to the vertebrae?","o":["Venous plexus (Batson)","Axillary lymph node metastases","Thoracic duct","Intercostal veins","Direct seeding"],"a":0,"e":"Batson venous plexus (vertebral venous plexus) is a valveless system connecting pelvic, breast, and prostate veins to vertebral venous channels; explains skeletal metastases from breast and prostate to spine.<br><br>Take Notes: Axillary nodes → drain breast lymphatics first | Thoracic duct → systemic | Vertebral metastases = Batson venous plexus."},
/*8*/ {"q":"Nasal endoscopy in a 40-year-old man reveals obstruction of the right superior meatus. Which of the following structures drains into this meatus?","o":["Posterior ethmoidal sinus","Anterior ethmoidal sinus","Maxillary sinus","Frontal sinus","Sphenoidal sinus"],"a":0,"e":"The superior nasal meatus drains posterior ethmoidal sinuses. Sphenoid drains into sphenoethmoidal recess above superior meatus. Maxillary, frontal, and anterior ethmoid drain into middle meatus.<br><br>Take Notes: Middle meatus → maxillary, frontal, anterior ethmoid | Sphenoethmoidal recess → sphenoid | Superior meatus = posterior ethmoidal."},
/*9*/ {"q":"During a neurosurgical procedure, the surgeon identifies the free margin of the tentorium cerebelli. This margin attaches to which of the following structures?","o":["Anterior clinoid process","Middle clinoid process","Posterior clinoid process","Sella turcica","Falx cerebelli"],"a":0,"e":"The free (inner) margin of tentorium cerebelli passes anteriorly to attach to the anterior clinoid process of sphenoid bone, encircling the brainstem at the tentorial notch. Fixed margin attaches to posterior clinoid.<br><br>Take Notes: Posterior clinoid → fixed margin | Sella turcica → pituitary | Tentorium free margin = anterior clinoid process."},
/*10*/ {"q":"Patient presented with peripheral numbness, diplopia and visual disturbance. Diagnosis of demyelinating disease was made. What types of cells are affected in this disease?","o":["Schwann cells","Oligodendrocytes","Astrocytes","Glial cells","Endothelial cells"],"a":1,"e":"Multiple sclerosis: autoimmune demyelinating disease of the CNS affecting oligodendrocytes (CNS myelin-producing cells). Schwann cells myelinate PNS (affected in GBS instead). Presents with relapsing-remitting neurological deficits.<br><br>Take Notes: Schwann cells → PNS myelination (GBS) | Astrocytes → support cells | CNS demyelination (MS) = oligodendrocytes."},
/*11*/ {"q":"Patient in RTA has fractured neck of fibula. Now is unable to dorsiflex and evert the foot. Which of the following nerves has been damaged?","o":["Deep peroneal nerve","Superficial peroneal nerve","Tibial nerve","Common peroneal nerve","Sural nerve"],"a":3,"e":"Common peroneal nerve winds around fibular neck — vulnerable to fracture; injury causes foot drop (loss of dorsiflexion via deep peroneal branch) and loss of eversion (via superficial peroneal branch).<br><br>Take Notes: Deep peroneal alone → only dorsiflexion lost | Superficial → only eversion | Both lost = common peroneal nerve."},
/*12*/ {"q":"A man presented with reducible swelling and positive cough impulse. A diagnosis of indirect inguinal hernia was made. What is the most likely cause of indirect inguinal hernia?","o":["Weak abdominal musculature","Diastasis recti","Patent processus vaginalis","Peritoneal tear","Incomplete membrane"],"a":2,"e":"Indirect inguinal hernia: persistent patent processus vaginalis (embryonic outpouching of peritoneum that should obliterate) allows abdominal contents to herniate through deep inguinal ring lateral to inferior epigastric vessels.<br><br>Take Notes: Direct hernia → weak abdominal wall | Diastasis recti → midline | Indirect inguinal hernia = patent processus vaginalis."},
/*13*/ {"q":"Women works with bended knees, now presents with swelling and knee pain due to involvement of:","o":["Suprapatellar bursa","Prepatellar bursa","Infrapatellar bursa","Sesamoid bursa","Meniscal tear"],"a":1,"e":"Prepatellar bursitis (\"housemaid's knee\"): swelling over the superficial aspect of the patella from repeated kneeling. Bursa lies between skin and patella; recurrent friction causes inflammation.<br><br>Take Notes: Infrapatellar (clergyman's knee) → below patella | Suprapatellar → joint effusion | Kneeling-related = prepatellar bursitis."},
/*14*/ {"q":"A lady with blood group Rh-ve has delivered a baby. A house officer is worried because the husband's blood group is Rh+ve. What hypersensitivity reaction she might have?","o":["Type I","Type II","Type III","Type IV","CD8 mediated"],"a":1,"e":"Hemolytic disease of the newborn (Rh incompatibility) is Type II hypersensitivity: maternal anti-Rh IgG antibodies cross placenta and target fetal Rh+ RBC antigens causing hemolysis.<br><br>Take Notes: Type I → IgE-mediated allergy | Type III → immune complex | Rh hemolytic disease = type II (antibody-mediated)."},
/*15*/ {"q":"Which of the following structures facilitates absorption of CSF and avoids hydrocephalus?","o":["Ependymal cells","Dural venous sinuses","Arachnoid granulations","Endothelial cells","Ventricles"],"a":2,"e":"Arachnoid granulations (villi) project into dural venous sinuses (superior sagittal sinus) and facilitate CSF absorption into venous blood. Obstruction causes communicating hydrocephalus.<br><br>Take Notes: Ependymal cells → CSF production (choroid plexus) | Sinuses → receive CSF | CSF absorption = arachnoid granulations."},
/*16*/ {"q":"A patient underwent mastectomy. Radiotherapy is planned; post surgery, what can be the side effects causing arm swelling?","o":["Infection","Neoplasia","Lymphedema","Fracture of the humerus","Hematoma"],"a":2,"e":"Lymphedema is the most common long-term complication after mastectomy with axillary lymph node dissection; lymphatic drainage disruption causes protein-rich fluid accumulation in arm. Radiotherapy worsens risk.<br><br>Take Notes: Infection → cellulitis (secondary) | Neoplasia → recurrence/lymphoma | Post-mastectomy arm swelling = lymphedema."},
/*17*/ {"q":"30-year-old patient done with esophagectomy, stomach is mobilized to upper portion to anastomose with pharynx. Which artery is responsible for the supply now?","o":["Left gastric","Right Gastric","Gastroduodenal artery","Right gastroepiploic","Left gastroepiploic"],"a":3,"e":"After esophagectomy, the gastric conduit (mobilized stomach) is supplied by right gastroepiploic artery, which courses along greater curvature; preserves perfusion to the gastric pull-up.<br><br>Take Notes: Left gastric → ligated for mobilization | Gastroduodenal → liver primarily | Gastric conduit = right gastroepiploic artery."},
/*18*/ {"q":"Cheilosis and corneal vascularization is due to deficiency of?","o":["Biotin","Riboflavin","Thiamine","Pantothenic Acid","Zinc"],"a":1,"e":"Vitamin B2 (riboflavin) deficiency: cheilosis (cracking at angles of mouth), glossitis, seborrheic dermatitis, and corneal vascularization. Riboflavin is essential cofactor for FMN and FAD coenzymes.<br><br>Take Notes: Thiamine → beriberi | Biotin → dermatitis + hair loss | Cheilosis + corneal vascularization = riboflavin."},
/*19*/ {"q":"A female patient presented with 3rd degree UV prolapse which occurs due to damage of uterosacral ligament. Which of the following structures attaches the uterosacral ligament to the cervix?","o":["Posterior pelvic wall","Rectum","Lumbar vertebrae","Symphysis pubis","Perineal body"],"a":0,"e":"Uterosacral ligaments are the chief posterior support of cervix and upper vagina; extend from posterolateral cervix to sacrum (S2-S4). Damage causes uterovaginal prolapse.<br><br>Take Notes: Round ligament → cervix to labia majora | Pubocervical → cervix to pubis | Uterosacral = cervix to posterior pelvic wall (sacrum)."},
/*20*/ {"q":"Edema fluid due to inflammation:","o":["Transudate","Exudate","Suppurative","Fibrinous","Straw colored"],"a":1,"e":"Exudate is inflammatory fluid with high protein content (>2.5 g/dL), high specific gravity (>1.020), and increased cells from raised vascular permeability. Transudate is pure hydrostatic.<br><br>Take Notes: Transudate → low protein, CHF | Suppurative → pus | Inflammatory edema = exudate."},
/*21*/ {"q":"A person presented with fever and infection. On gram staining, G+ cocci, coagulase and catalase positive were isolated. The virulence of such organism is due to?","o":["IgA Protease","Protein S","Protein A","Catalase positivity","Coagulase"],"a":2,"e":"Staphylococcus aureus (G+ cocci, catalase and coagulase positive): Protein A on cell wall binds Fc region of IgG, preventing opsonization and phagocytosis — key virulence factor.<br><br>Take Notes: Catalase → distinguishes Staph from Strep but not main virulence | IgA protease → other organisms | S. aureus virulence = Protein A."},
/*22*/ {"q":"A child is progressively unable to hear at loud sounds due to damage to?","o":["Organ of Corti","Scala vestibule","Scala media","Neural pathway","Pinna of ear"],"a":0,"e":"The Organ of Corti contains outer and inner hair cells in the cochlea; loud noise damages these mechanoreceptors causing sensorineural hearing loss. Outer hair cells are most susceptible to noise.<br><br>Take Notes: Scala media → contains organ of Corti | Pinna → external | Loud noise hearing loss = organ of Corti damage."},
/*23*/ {"q":"Which of the following Anti-HIV drugs is contraindicated in pregnancy?","o":["Didanosine","Efavirenz","Indinavir","Zidovudine","Omeprazole"],"a":1,"e":"Efavirenz is teratogenic in first trimester (category D — NTDs in animal studies); contraindicated in pregnancy. Zidovudine, lamivudine, tenofovir are preferred and used to prevent mother-to-child transmission.<br><br>Take Notes: Zidovudine → ART of choice (PMTCT) | Indinavir → no teratogenicity | Pregnancy contraindicated = efavirenz."},
/*24*/ {"q":"A patient presented with right groin swelling. It is located lateral and inferior to pubic tubercle. What is the most likely diagnosis?","o":["Inguinal Hernia","Hydrocele","Femoral Hernia","Psoas abscess","Femoral aneurysm"],"a":2,"e":"Femoral hernia: swelling lateral and inferior to pubic tubercle (vs inguinal which is medial and superior). More common in females; high risk of strangulation due to narrow femoral canal.<br><br>Take Notes: Inguinal → above + medial to pubic tubercle | Psoas abscess → above inguinal ligament | Below + lateral PT = femoral hernia."},
/*25*/ {"q":"During submandibular gland excision, which of the following structures can cause paralysis of the lower lip?","o":["Marginal Mandibular branch","Lingual nerve","Hypoglossal nerve","Facial artery","Trigeminal Nerve"],"a":0,"e":"Marginal mandibular branch of facial nerve passes near lower border of mandible above submandibular gland; injury during surgery causes paralysis of lower lip depressor muscles producing asymmetric smile.<br><br>Take Notes: Lingual nerve → tongue sensation | Hypoglossal → tongue motor | Submandibular surgery + lower lip palsy = marginal mandibular."},
/*26*/ {"q":"Cells responsible for repair process in the CNS?","o":["Oligodendrocytes","Fibroblasts","Schwann cells","Microglial cells","Astrocytes"],"a":4,"e":"Astrocytes proliferate at the lesion edges to form glial scar (gliosis) — CNS equivalent of fibrous scarring. Microglia clear debris early; astrogliosis becomes dominant in repair phase.<br><br>Take Notes: Microglia → CNS macrophages (early) | Oligodendrocytes → myelination | CNS repair scar = astrocytes (gliosis)."},
/*27*/ {"q":"A patient with skull fracture after RTA is scheduled for surgery. The surgeon should take extra precautions to prevent?","o":["Air embolism","Fat embolism","Amniotic fluid embolism","Caissons disease","Pulmonary embolism"],"a":0,"e":"During skull/neurosurgery (especially sitting position or with dural sinus injury), air can enter venous sinuses causing fatal venous air embolism. Precautions include head-down positioning and meticulous hemostasis.<br><br>Take Notes: Fat embolism → long bone fracture | PE → leg DVT | Skull surgery risk = air embolism."},
/*28*/ {"q":"A person presented with diarrhoea and memory loss. He is also having stomatitis, esophagitis and dermatitis. Which of the following deficiencies most likely contribute to these symptoms?","o":["Thiamine","Biotin","Riboflavin","Niacin","Cobalamin"],"a":3,"e":"Pellagra (niacin/vitamin B3 deficiency): classic triad of \"4 D's\" — Diarrhea, Dermatitis (photosensitive), Dementia, and Death if untreated. Niacin is required for NAD/NADP synthesis.<br><br>Take Notes: Thiamine → beriberi, Wernicke | Riboflavin → cheilosis | Pellagra (4 Ds) = niacin deficiency."},
/*29*/ {"q":"Person with difficulty in swallowing. There is some white growth inside esophagus with pseudohyphae. Likely reason is:","o":["Oral leukoplakia","Candida albicans","Herpes simplex infection","Aphthous ulcer","C. diphtheria"],"a":1,"e":"Candida albicans causes oesophageal candidiasis with white plaques and pseudohyphae; common in immunocompromised (HIV, diabetes, steroids). Dysphagia and odynophagia are typical symptoms.<br><br>Take Notes: Leukoplakia → keratotic, no pseudohyphae | HSV → vesicles | White growth + pseudohyphae = Candida."},
/*30*/ {"q":"A female presented with an ovarian cyst. The marker likely used to check its progression is?","o":["CA 15-3","CA 19-9","CA 125","Alpha fetoprotein","CEA"],"a":2,"e":"CA 125 is the primary tumor marker for epithelial ovarian cancer (raised in >80% of serous type); used for monitoring disease progression and detecting recurrence. Also elevated in endometriosis.<br><br>Take Notes: CA 15-3 → breast | CA 19-9 → pancreas | AFP → yolk sac, HCC | Ovarian cyst/cancer = CA 125."},
/*31*/ {"q":"Failure of cranial neuropore closure causes:","o":["Anencephaly","Meningocele","Spina bifida occulta","Myelomeningocele","Meningoencephalocele"],"a":0,"e":"Anencephaly results from failure of cranial (rostral) neuropore closure (~25 days); brain and skull vault don't develop. Incompatible with life. Often presents with elevated maternal serum AFP.<br><br>Take Notes: Caudal neuropore failure → spina bifida | Spina bifida occulta → vertebral arch defect | Cranial neuropore failure = anencephaly."},
/*32*/ {"q":"A patient sustained a trauma during an accident which caused head of the femur to displace in posterior direction. Which nerve is most likely damaged?","o":["Femoral nerve","Sciatic nerve","Obturator nerve","Tibial nerve","CPN"],"a":1,"e":"Posterior hip dislocation classically injures the sciatic nerve as it exits the greater sciatic foramen close to the posterior aspect of acetabulum. Presents with foot drop and sensory loss.<br><br>Take Notes: Anterior hip dislocation → femoral nerve | Femoral neck fracture → medial circumflex | Posterior hip dislocation = sciatic nerve."},
/*33*/ {"q":"A primigravida presented to clinic in second trimester and mentioned that she can feel some movements in her abdomen. The doctor said it is normal and shows that the fetus is normal and healthy. In which week does the mother first feel fetal movements?","o":["12 weeks","16 weeks","18 weeks","20 weeks","Post partum"],"a":3,"e":"Quickening (first maternal perception of fetal movements) typically occurs around 18-20 weeks in primigravida; earlier (16-18 weeks) in multigravida who has experienced it before. Marker of fetal viability.<br><br>Take Notes: Multigravida → 16-18 weeks | Quickening = normal milestone | Primigravida quickening = 20 weeks."},
/*34*/ {"q":"A 56-year-old male presented with tremors, rigidity and bradykinesia. Loss of which of the following neurotransmitters in basal ganglia is responsible for Parkinson's?","o":["GABAminergic","Dopaminergic","Acetylcholine","Glutamate","Nucleus basalis of Meynert"],"a":1,"e":"Parkinson disease: degeneration of dopaminergic neurons in substantia nigra pars compacta causes loss of dopamine input to striatum; produces resting tremor, rigidity, bradykinesia, and postural instability.<br><br>Take Notes: ACh loss → Alzheimer (nucleus basalis of Meynert) | GABA loss → Huntington | Parkinson = dopamine loss (substantia nigra)."},
/*35*/ {"q":"Closest to crus cerebri lies:","o":["Substantia Nigra","Internal Capsule","Thalamus","Tectum","Glabella"],"a":0,"e":"The crus cerebri (basis pedunculi) of midbrain carries descending motor fibers; substantia nigra lies immediately deep (dorsal) to it. Both are part of the cerebral peduncle of midbrain.<br><br>Take Notes: Tectum → dorsal midbrain (colliculi) | Thalamus → diencephalon | Adjacent to crus cerebri = substantia nigra."},
/*36*/ {"q":"A 40-year-old woman with schizophrenia started a new antipsychotic medication 3 weeks ago. Her symptoms have improved. On a hot day, she takes a long walk and is later found unconscious on the ground. Which medication is most likely responsible for the heat stroke?","o":["Lithium","Buspirone","Haloperidol","Entacapone","Amitriptyline"],"a":2,"e":"Haloperidol (typical antipsychotic) impairs thermoregulation by blocking dopamine receptors in hypothalamus and through anticholinergic action; can precipitate heat stroke especially with exertion in heat.<br><br>Take Notes: Lithium → polyuria + tremor | Buspirone → anxiolytic | Antipsychotic heat stroke = haloperidol."},
/*37*/ {"q":"A 45-year-old man presents with numbness over the lateral three and a half digits of the hand and visible wasting of the thenar eminence. Which nerve is most likely damaged?","o":["Ulnar nerve","Median nerve","Radial nerve","Musculocutaneous nerve","Sural nerve"],"a":1,"e":"Median nerve supplies lateral 3.5 digits sensation and thenar muscles (LOAF — Lumbricals 1-2, Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis). Carpal tunnel syndrome typical presentation.<br><br>Take Notes: Ulnar → medial 1.5 digits + hypothenar | Radial → posterior arm strip | Lateral 3.5 + thenar = median."},
/*38*/ {"q":"A patient with median nerve injury is examined for functional loss. Which muscle is most likely affected?","o":["First lumbrical","Third lumbrical","Abductor pollicis longus","Palmar interossei","Abductor digiti minimi"],"a":0,"e":"Median nerve supplies thenar muscles (LOAF) and 1st and 2nd lumbricals; median injury affects first lumbrical (lateral two). Third and fourth lumbricals are ulnar nerve territory.<br><br>Take Notes: Abductor pollicis longus → radial | Palmar interossei → ulnar | Median = first 2 lumbricals + thenar (LOAF)."},
/*39*/ {"q":"A 10-year-old boy sustains a head injury during sports. He has diplopia and a convergent squint on examination. Imaging shows a fracture involving the sphenoid bone. Which part is most likely damaged?","o":["Greater wing of sphenoid","Angle of sphenoid","Body of sphenoid","Pterygoid process","Frontal bone"],"a":2,"e":"Body of sphenoid contains cavernous sinus through which CN VI (abducens) passes; injury causes lateral rectus palsy with convergent squint and diplopia. CN VI has the longest intracranial course making it vulnerable.<br><br>Take Notes: Greater wing → middle cranial fossa | Pterygoid → masticatory | Sphenoid body fracture + abducens palsy."},
/*40*/ {"q":"Fracture through the foramen ovale is most likely to spare which muscle?","o":["Tensor tympani","Mylohyoid","Anterior belly of digastric","Posterior belly of digastric","Tensor palatini"],"a":3,"e":"Foramen ovale transmits mandibular nerve (V3) which supplies tensor tympani, mylohyoid, anterior digastric, tensor palatini, and muscles of mastication. Posterior digastric is facial nerve-supplied, so spared.<br><br>Take Notes: V3 muscles → all suffer | Posterior digastric = facial nerve (VII) | Foramen ovale spares = posterior digastric."},
/*41*/ {"q":"A 30 y/o woman has a history of delivery with significant blood loss after which she could not lactate. Deficiency of which of the following is the most likely cause for this presentation?","o":["TSH","GnRH","Cortisol","ACTH","Prolactin"],"a":4,"e":"Sheehan syndrome: postpartum pituitary necrosis from severe haemorrhage causing anterior hypopituitarism. Prolactin deficiency causes failure to lactate (earliest sign); other anterior pituitary hormones (TSH, ACTH, FSH/LH, GH) also affected.<br><br>Take Notes: ACTH loss → cortisol deficiency, dizziness | TSH loss → late myxedema | No lactation post-partum = prolactin deficiency."},
/*42*/ {"q":"Which of the following muscle passes through greater sciatic foramen and is prone to damage here?","o":["Piriformis","Gluteus minimus","Obturator internus","Quadratus femoris","Pisiform"],"a":0,"e":"Piriformis is the principal muscle passing through greater sciatic foramen, dividing it into suprapiriform and infrapiriform compartments. Piriformis syndrome causes sciatic nerve compression and gluteal pain.<br><br>Take Notes: Obturator internus → lesser sciatic foramen | Gluteus minimus → no sciatic foramen | Greater sciatic foramen muscle = piriformis."},
/*43*/ {"q":"The parasympathetic nuclei for S2-S4 spinal segments are located opposite which vertebral levels?","o":["T10-T12","L1-L2","L3-L4","L5-S1","S4"],"a":1,"e":"Due to ascensus medullaris, the spinal cord ends at L1-L2 in adults. Parasympathetic sacral nuclei (S2-S4 cord segments) lie at L1-L2 vertebral level — the conus medullaris region.<br><br>Take Notes: Cord ends at L1-L2 | Cauda equina → L1-L5 nerve roots | S2-S4 cord segments = L1-L2 vertebral level."},
/*44*/ {"q":"A 45-year-old woman presents with sudden episodes of waking at night feeling breathless. Cardiac examination reveals a diastolic murmur with an opening snap. Which of the following is the most likely diagnosis?","o":["Aortic regurgitation","Mitral stenosis","Tricuspid stenosis","Pulmonic stenosis","Aortic stenosis"],"a":1,"e":"Mitral stenosis: diastolic murmur with opening snap at apex; paroxysmal nocturnal dyspnea from pulmonary congestion. Usually from rheumatic heart disease. Loud S1 and presystolic accentuation may be present.<br><br>Take Notes: Aortic regurg → diastolic, no opening snap | Aortic stenosis → systolic | Opening snap + diastolic murmur = mitral stenosis."},
/*45*/ {"q":"A 32-year-old woman in her third trimester of pregnancy complains of intermittent pain in her medial thigh when standing. Examination reveals no neurologic deficits. The doctor reassures her this is a normal finding due to stretching or compression of which structure?","o":["Obturator nerve","Ilioinguinal nerve","Femoral nerve","Genitofemoral nerve","Due to stretch of the inguinal ligament"],"a":0,"e":"Obturator nerve passes through obturator canal; in third trimester, gravid uterus can compress it causing medial thigh pain (Howship-Romberg sign). Usually benign and resolves postpartum.<br><br>Take Notes: Ilioinguinal → upper medial thigh + scrotum | Femoral → anterior thigh | Pregnant + medial thigh pain = obturator nerve."},
/*46*/ {"q":"A 6-year-old boy presents with recurrent bacterial and fungal infections. Neutrophils from this patient fail to produce superoxide radicals during the oxidative burst. This defect is most likely due to a deficiency in which enzyme?","o":["NADPH oxidase","Myeloperoxidase","Catalase","Superoxide dismutase","Metalloproteinase"],"a":0,"e":"Chronic granulomatous disease (CGD): NADPH oxidase deficiency impairs neutrophil respiratory burst; cannot kill catalase-positive organisms (Staph, Aspergillus, Burkholderia, Serratia, Nocardia). Diagnosed with abnormal NBT or DHR test.<br><br>Take Notes: MPO deficiency → mild Candida | SOD → mitochondrial role | Failed respiratory burst = NADPH oxidase deficiency."},
/*47*/ {"q":"A 4-year-old boy presents with self-mutilating behavior, involuntary movements, and developmental delay. Laboratory testing shows hyperuricemia. Most likely diagnosis?","o":["Lesch-Nyhan syndrome","Tay-Sachs disease","Hurler syndrome","Krabbe disease","Niemann-Pick disease"],"a":0,"e":"Lesch-Nyhan syndrome: X-linked HGPRT deficiency causes hyperuricemia, gouty arthritis, renal stones, intellectual disability, choreoathetosis, and characteristic self-mutilation (lip/finger biting).<br><br>Take Notes: Tay-Sachs → cherry red spot, no self-mutilation | Hurler → coarse facies, corneal clouding | Self-mutilation + hyperuricemia = Lesch-Nyhan."},
/*48*/ {"q":"A 50-year-old woman presents with fever, jaundice, and right upper quadrant pain radiating to her shoulder. The gallbladder is not palpable. Laboratory tests reveal elevated alkaline phosphatase and conjugated hyperbilirubinemia. Most likely diagnosis?","o":["Acute cholecystitis","Choledocholithiasis causing obstruction","Ascending cholangitis","Gallbladder carcinoma","Empyema"],"a":2,"e":"Ascending cholangitis: Charcot triad (fever, jaundice, RUQ pain) ± Reynolds pentad (with hypotension, altered mental status). Caused by obstruction (usually stones) and bacterial infection of biliary system.<br><br>Take Notes: Acute cholecystitis → no jaundice usually | Choledocholithiasis → silent stone | Charcot triad = ascending cholangitis."},
/*49*/ {"q":"A 16-year-old boy is diagnosed with Klinefelter syndrome. Which of the following karyotypes is most consistent with this condition?","o":["47, XXY","47, XYY","45, XO","46, XY","49, XXXY"],"a":0,"e":"Klinefelter syndrome: 47,XXY karyotype (extra X chromosome); tall stature, gynecomastia, small testes, infertility, learning difficulties. Most common cause of male hypogonadism.<br><br>Take Notes: 47,XYY → tall, normal | 45,XO → Turner | 47,XXY = Klinefelter (most common male hypogonadism)."},
/*50*/ {"q":"A pregnant woman with history of being bedridden, develops sudden chest pain and dyspnea. She has history of a long flight. On examination, she has a swollen and tender calf. Chest and cardiac examination are normal. Which of the following is the most likely diagnosis?","o":["Pulmonary embolism","Myocardial infarction","Aortic dissection","Pneumothorax","Amniotic fluid embolism"],"a":0,"e":"Pulmonary embolism from DVT: pregnancy + immobilization + long flight = Virchow's triad. Calf swelling indicates DVT; sudden dyspnea and pleuritic chest pain indicate embolization to lung. PE common in pregnancy.<br><br>Take Notes: Aortic dissection → tearing pain back | Amniotic fluid embolism → during labor | Pregnant + DVT + sudden dyspnea = PE."},
/*51*/ {"q":"A patient is lying supine during pulmonary examination. Which of the following describes the normal relationship of pulmonary arterial pressures to alveolar pressure in the apex of the lung?","o":["Systolic and diastolic pressure < alveolar pressure","Systolic pressure <; alveolar pressure","Systolic and diastolic pressure > alveolar pressure","Systolic pressure < alveolar pressure, diastolic > alveolar pressure","Equal pressures"],"a":0,"e":"In supine position, alveolar pressure > both systolic and diastolic pulmonary arterial pressures at lung apex (Zone 1 conditions); blood flow there is impeded. Upright position exaggerates this.<br><br>Take Notes: Zone 2 (middle) → systolic > alveolar > diastolic | Zone 3 (base) → both > alveolar | Apex zone 1 = alveolar > both."},
/*52*/ {"q":"After a road traffic accident, a patient cannot extend the hip or flex the knee. Imaging reveals an avulsion fracture. Which site is most likely involved?","o":["Ischial tuberosity","Anterior superior iliac spine","Neck of femur","Greater trochanter","Medial meniscus"],"a":0,"e":"Ischial tuberosity gives origin to hamstrings (knee flexors and hip extensors); its avulsion fracture causes loss of both knee flexion and hip extension. Common in sports injuries.<br><br>Take Notes: ASIS → sartorius (hip flex + knee flex) | Greater trochanter → gluteus medius | Hip extension + knee flexion loss = ischial tuberosity."},
/*53*/ {"q":"A 28-year-old runner twisted his ankle during a trail race and now has burning pain and numbness on the plantar surface of his foot. On examination there is weakness of toe flexion. A Tinel-like sign is positive posterior to the medial malleolus. Which nerve is most likely compressed in the tarsal tunnel?","o":["Sural nerve","Superficial peroneal nerve","Tibial nerve","Deep peroneal nerve","Saphenous nerve"],"a":2,"e":"Tarsal tunnel syndrome: compression of posterior tibial nerve beneath flexor retinaculum behind medial malleolus; presents with burning pain, paresthesia in sole, weakness of toe flexors, and positive Tinel sign.<br><br>Take Notes: Sural → lateral foot | Saphenous → medial leg | Tarsal tunnel = posterior tibial nerve."},
/*54*/ {"q":"A 22-year-old man arrives at the emergency department after a motorbike crash. He is pale, tachycardic, and has a large pulsatile wound with bright red bleeding from his thigh. He is also short of breath and becoming confused. Which immediate action should be taken first?","o":["Establish and secure the airway","Apply direct pressure/tourniquet to control catastrophic hemorrhage","Begin blood transfusion","Perform a chest X-ray to assess thoracic injury","Immediate laparotomy"],"a":1,"e":"In catastrophic external haemorrhage (ATLS \"C-ABCDE\" or \"<C>ABC\" approach): control of catastrophic bleeding precedes airway management; otherwise patient exsanguinates before airway can be secured. Direct pressure/tourniquet first.<br><br>Take Notes: Standard ATLS → ABCDE | Severe hemorrhage → C first (<C>ABC) | Catastrophic bleed = direct pressure first."},
/*55*/ {"q":"A patient is diagnosed with generalized lymphadenopathy and a large B-cell lymphoma. What is the treatment of choice?","o":["Radiotherapy alone","Combined surgery and radiotherapy","Chemotherapy alone","Watchful waiting","Palliative therapy"],"a":2,"e":"Diffuse large B-cell lymphoma (DLBCL) treatment: R-CHOP chemotherapy (rituximab + cyclophosphamide, doxorubicin, vincristine, prednisone) is the standard regimen; complete remission in 60-70%, curable in many cases.<br><br>Take Notes: Surgery → not for systemic disease | Watchful waiting → indolent lymphomas | DLBCL = R-CHOP chemotherapy."},
/*56*/ {"q":"The internal capsule is composed of which of the following?","o":["Gray matter","White matter","Choroid plexus tissue","Cerebellar cortex","Plasma cells"],"a":1,"e":"Internal capsule is composed of white matter (myelinated fibers): contains corticospinal, corticobulbar, corticopontine fibers, and thalamic radiations. Functions as relay between cortex and subcortical/brainstem structures.<br><br>Take Notes: Gray matter → cortex, nuclei | Cerebellar cortex → different structure | Internal capsule = white matter (projection fibers)."},
/*57*/ {"q":"A laminectomy is planned. Which of the following structures is to be involved?","o":["Transverse process","Spinous process","Pedicle","Vertebral body","Rib anteriorly"],"a":1,"e":"Laminectomy: surgical removal of the vertebral lamina (and spinous process) to decompress spinal cord/nerve roots. Common procedure for spinal stenosis, disc herniation, or accessing the spinal canal.<br><br>Take Notes: Transverse process → distinct procedure | Pedicle → screws | Laminectomy = spinous process + lamina removal."},
/*58*/ {"q":"A nurse is organizing a lecture on technique of gluteal injections. The safe technique to use is important to avoid damage to?","o":["Femoral nerve","Obturator nerve","Sciatic nerve","Superior gluteal nerve","Popliteal Nerve"],"a":2,"e":"Sciatic nerve is at risk during gluteal IM injections; the safe area is the upper outer quadrant of buttock, lateral to a line from PSIS to greater trochanter, to avoid sciatic nerve injury.<br><br>Take Notes: Superior gluteal → upper area | Femoral → anterior | Gluteal injection risk = sciatic nerve."},
/*59*/ {"q":"Which structure primarily transmits load from femur to tibia?","o":["Collateral ligaments","Menisci","Anterior cruciate ligament","Popliteus tendon","Capsule of the joint"],"a":1,"e":"Menisci (medial and lateral) transmit and distribute axial load from femur to tibia at the knee joint; act as shock absorbers and increase joint contact area. Meniscal tears impair load transmission.<br><br>Take Notes: ACL → prevents anterior tibial translation | Collateral → side-to-side | Load transmission knee = menisci."},
/*60*/ {"q":"Which structure provides the main dynamic stability for the glenohumeral joint?","o":["Deltoid","Rotator cuff muscles","Pectoralis major and minor","Latissimus dorsi and teres major","Glenoid"],"a":1,"e":"Rotator cuff (SITS — supraspinatus, infraspinatus, teres minor, subscapularis) provides dynamic stability of glenohumeral joint by compressing humeral head into glenoid during movement.<br><br>Take Notes: Deltoid → abduction power | Glenoid → static (passive) | Shoulder dynamic stability = rotator cuff (SITS)."},
/*61*/ {"q":"During an embryology lecture, you are asked which embryologic structure largely contributes to the central tendon of the adult diaphragm. Which is the correct origin?","o":["Cervical myotomes (C3-C5)","Septum transversum","Lateral plate mesoderm of the abdomen","Neural crest cells","Peritoneal covering"],"a":1,"e":"Septum transversum forms the central tendon of the diaphragm. Cervical myotomes (C3-C5) contribute muscular portions and explain phrenic nerve innervation. Pleuroperitoneal folds form posterolateral portions.<br><br>Take Notes: C3-C5 myotomes → muscular + phrenic nerve | Pleuroperitoneal folds → posterolateral | Central tendon = septum transversum."},
/*62*/ {"q":"A 24-year-old man is in a road traffic accident and on exam has a segment of the chest wall moving paradoxically. He is short of breath and hypoxic. Which of the following best describes his injury?","o":["Open pneumothorax","Flail chest","Tension pneumothorax","Myocardial contusion","Eisenmenger syndrome"],"a":1,"e":"Flail chest: ≥3 adjacent ribs fractured in ≥2 places produce paradoxical movement of chest segment (inward during inspiration). Causes hypoxia from pulmonary contusion and inefficient ventilation.<br><br>Take Notes: Open pneumothorax → sucking chest wound | Tension → mediastinal shift | Paradoxical chest movement = flail chest."},
/*63*/ {"q":"A child presents with prolonged bleeding after circumcision and laboratory testing suggests a vitamin K deficiency. Vitamin K is essential for which of the following mechanisms in clotting factor maturation?","o":["Formation of gamma carboxyglutamic acid residues","Hydroxylation of proline residues on collagen","Activation of fibrinogen to fibrin by thrombin","Cleavage of factor X to Xa by factor VIIa","Formation of clotting factors"],"a":0,"e":"Vitamin K is cofactor for gamma-glutamyl carboxylase, which adds carboxyl groups (gamma-carboxyglutamic acid residues) to glutamic acid on factors II, VII, IX, X, and proteins C/S — essential for calcium binding.<br><br>Take Notes: Proline hydroxylation → vitamin C (collagen) | Thrombin → fibrinogen direct conversion | Vitamin K = gamma-carboxylation."},
/*64*/ {"q":"A 62-year-old man with long-standing chronic liver disease develops progressive peripheral edema and ascites. Which primary mechanism best explains his generalized edema?","o":["Increased capillary oncotic pressure","Decreased plasma oncotic (colloid) pressure","Primary lymphatic obstruction","Generalized capillary leakage from systemic inflammation","Increased hydrostatic pressure"],"a":1,"e":"Chronic liver disease: decreased hepatic albumin synthesis causes hypoalbuminemia and decreased plasma oncotic (colloid) pressure; fluid moves from intravascular to interstitial space causing edema and ascites.<br><br>Take Notes: Cardiac edema → increased hydrostatic | Lymphedema → lymphatic obstruction | Cirrhotic edema = decreased oncotic pressure."},
/*65*/ {"q":"While sitting in a park, a child feels a bee sting. Which receptor is primarily responsible for the sensation?","o":["Merkel discs","Pacinian corpuscles","Nociceptors","Meissner corpuscles","Muscle spindle"],"a":2,"e":"Nociceptors (free nerve endings) detect noxious stimuli (pain, burning, tissue damage); activated by bee sting venom. They transmit via Aδ (fast, sharp pain) and C (slow, dull pain) fibers.<br><br>Take Notes: Merkel → light touch | Pacinian → deep pressure/vibration | Meissner → discriminative touch | Pain = nociceptors."},
/*66*/ {"q":"After proliferative stage of wound healing, it is replaced by which collagen?","o":["Fibroblasts","Macrophages","Collagen I","Collagen III","Collagen IV"],"a":2,"e":"In wound healing remodelling phase (weeks-months), collagen III (laid down in granulation tissue) is gradually replaced by collagen I (mature, cross-linked, stronger); increases tensile strength of scar.<br><br>Take Notes: Collagen III → fetal/early wound (thin, flexible) | Collagen IV → basement membrane | Mature scar = collagen I (cross-linked)."},
/*67*/ {"q":"A patient with an acute occlusion of the renal artery presents with sudden flank pain and anuria. For best chance of salvaging renal function, revascularization should be attempted within which approximate time window?","o":["Less than 30 minutes","Less than 2 hours","Less than 1 hour","More than 72 hours","Within 12-24 hours"],"a":2,"e":"Acute renal artery occlusion: revascularization should be attempted within 1 hour for best chance of salvaging renal function. Beyond this, irreversible ischemic damage occurs; >3-6 hours typically results in irreversible loss.<br><br>Take Notes: Brain → 3-5 minutes critical | Heart → 20-40 minutes | Kidney = <1 hour for revascularization."},
/*68*/ {"q":"In a blood bank, after some time there is loss of 2,3-BPG in the blood pack. What physiological changes can happen secondarily to this change?","o":["Rightward shift of oxygen dissociation curve with decreased affinity","Leftward shift of oxygen dissociation curve with increased oxygen affinity","No change in oxygen affinity but decreased CO2 transport","Leftward shift with decreased affinity","Rightward shift with increased affinity"],"a":1,"e":"2,3-BPG (DPG) normally binds β-globin chains and decreases hemoglobin's O2 affinity; loss in stored blood causes leftward shift of ODC (increased O2 affinity but impaired O2 delivery to tissues).<br><br>Take Notes: 2,3-BPG decreases → ↑ O2 affinity → leftward shift | Acidosis/exercise → rightward shift | Stored blood = leftward shift."},
/*69*/ {"q":"An infant is born with 8th CN damage along with Hutchinson teeth. These findings are most suggestive of what?","o":["Congenital syphilis","Congenital rubella","Cytomegalovirus","Toxoplasmosis","Herpes simplex"],"a":0,"e":"Congenital syphilis: classic triad — Hutchinson teeth (notched incisors), interstitial keratitis, and 8th cranial nerve deafness. Other features: saddle nose, saber shins, mulberry molars.<br><br>Take Notes: Congenital rubella → cataracts + cardiac defects + deafness | CMV → periventricular calcifications | Hutchinson teeth + deafness = congenital syphilis."},
/*70*/ {"q":"A patient presents with diplopia, loss of facial sweating on one side, and constricted pupil ipsilaterally. Which part of the nervous system is most likely damaged?","o":["Parasympathetic fibers of cranial nerve III","Facial nerve (VII, peripheral branch)","Trigeminal nerve motor root","Cervical sympathetic chain","Pterygopalatine ganglion"],"a":3,"e":"Horner syndrome: cervical sympathetic chain interruption causes ipsilateral ptosis, miosis (constricted pupil), and anhidrosis (loss of facial sweating). Diplopia may occur if cranial nerves nearby affected (e.g., Pancoast tumor).<br><br>Take Notes: CN III → would cause mydriasis (dilated) | Facial nerve → motor weakness | Miosis + anhidrosis + ptosis = Horner (cervical sympathetic)."},
/*71*/ {"q":"In a 65-year-old patient, there is a palpable, firm, non-tender lymph node under the chin. Which lymph nodes are most likely involved first in the metastatic spread of lower lip carcinoma?","o":["Parotid lymph nodes","Submandibular lymph nodes","Deep cervical lymph nodes","Jugulodigastric lymph nodes","Submental lymph nodes"],"a":4,"e":"Lower lip and chin drain to submental (sublingual) lymph nodes; lower lip carcinoma first metastasizes to these submental nodes (under chin), then submandibular and deep cervical chain.<br><br>Take Notes: Upper lip → submandibular | Tongue → cervical/submandibular | Lower lip + chin = submental nodes."},
/*72*/ {"q":"A 40-year-old construction worker with a history of chronic sun exposure presents with a firm, scaly lesion on the forehead that has been enlarging for 6 months. Biopsy confirms squamous cell carcinoma. Which of the following best describes the molecular mechanism by which UVB radiation induces such skin malignancies?","o":["Frameshift mutation in Rb gene","Formation of pyrimidine dimers leading to p53 inactivation","Activation of mismatch repair genes","Translocation involving the C-myc oncogene","Point mutation in β-catenin gene"],"a":1,"e":"UVB radiation forms pyrimidine dimers (thymine dimers) in DNA which, if unrepaired, lead to p53 mutations and inactivation. p53 normally prevents damaged cells from replicating; its loss promotes carcinogenesis.<br><br>Take Notes: C-myc → Burkitt | β-catenin → colon CA | UV → SCC/BCC via pyrimidine dimers + p53."},
/*73*/ {"q":"Oncofetal tumor marker used in adenocarcinoma of colon:","o":["CA 15-3","CA 19-9","CA 125","Alpha fetoprotein","CEA"],"a":4,"e":"CEA (carcinoembryonic antigen) is an oncofetal tumor marker raised in colorectal adenocarcinoma; used for postoperative monitoring of disease recurrence. Also raised in smokers and other malignancies (less specific).<br><br>Take Notes: CA 19-9 → pancreatic | AFP → HCC, yolk sac | CA 125 → ovarian | Colon adenocarcinoma = CEA."},
/*74*/ {"q":"A 45-year-old man with a history of chronic hepatitis B presents with right upper quadrant pain, weight loss, and jaundice. Ultrasound reveals a large hepatic mass, and serum studies are ordered to aid in diagnosis. Which tumor marker is most likely elevated in this patient?","o":["CA 15-3","CA 19-9","CA 125","Alpha-fetoprotein","CEA"],"a":3,"e":"Hepatocellular carcinoma (HCC) on background of chronic hepatitis B: alpha-fetoprotein (AFP) is the principal tumor marker; elevated in 70% of HCC. Used for screening high-risk patients and monitoring response.<br><br>Take Notes: CEA → colon | CA 19-9 → pancreas | CA 125 → ovarian | HCC = AFP."},
/*75*/ {"q":"A 28-year-old woman is trying to conceive and has been advised by the doctor to check temperature daily so that she can be aware of her ovulatory phase. Which hormone is primarily responsible for post-ovulatory temperature increase?","o":["Follicle stimulating hormone","Luteinizing hormone","Estrogen","Gonadotropin-releasing hormone","Progesterone"],"a":4,"e":"Progesterone (from corpus luteum) is thermogenic and raises basal body temperature by 0.3-0.5°C after ovulation; sustained elevation indicates ovulation has occurred. Returns to baseline if no pregnancy.<br><br>Take Notes: Estrogen → preovulatory dip | LH → ovulation trigger | Post-ovulatory temp rise = progesterone."},
/*76*/ {"q":"A 15-year-old girl is evaluated for delayed puberty and short stature. She has a broad chest, widely spaced nipples, and a webbed neck. Echocardiography is ordered as part of her work-up. Which of the following cardiac anomalies is most commonly associated with this condition?","o":["Ventricular septal defect","Total anomalous pulmonary venous return","Bicuspid aortic valve and coarctation of the aorta","Tetralogy of Fallot","Pulmonary valve stenosis"],"a":2,"e":"Turner syndrome cardiac defects: bicuspid aortic valve (most common, ~30%) and coarctation of the aorta (~10%). Causes hypertension; bicuspid valve increases risk of aortic stenosis and dissection.<br><br>Take Notes: VSD → Down syndrome | TOF → 22q11 | Turner cardiac = bicuspid AV + coarctation."},
/*77*/ {"q":"A 29-year-old woman presents with intermittent diplopia, numbness in her right hand, and tingling in her left foot. Symptoms have been recurring over the past year. Neurological examination shows bilateral internuclear ophthalmoplegia and decreased sensation in the extremities. MRI demonstrates demyelinating lesions in the CNS. Which of the following is the most likely diagnosis?","o":["Guillain-Barré syndrome","Myasthenia gravis","Multiple sclerosis","Progressive multifocal leukoencephalopathy","Lambert-Eaton syndrome"],"a":2,"e":"Multiple sclerosis: autoimmune demyelinating disease with neurological deficits separated in time and space; internuclear ophthalmoplegia is classic. MRI shows white matter lesions; CSF oligoclonal bands support diagnosis.<br><br>Take Notes: GBS → ascending paralysis, post-infection | MG → fatigability | INO + lesions = MS."},
/*78*/ {"q":"A 52-year-old man presents with pallor and fatigue. Laboratory studies show hemoglobin of 9.0 g/dL, elevated serum homocysteine, and normal methylmalonic acid levels. Which of the following is the most likely cause of his anemia?","o":["Vitamin B12 deficiency","Folic acid deficiency","Iron deficiency","Sideroblastic anemia","Anemia of chronic disease"],"a":1,"e":"Folate deficiency: elevated homocysteine with NORMAL methylmalonic acid (MMA). B12 deficiency would elevate both. Megaloblastic anemia results; B12 needed for MMA→succinyl-CoA, folate needed for homocysteine→methionine.<br><br>Take Notes: B12 def → ↑ homocysteine + ↑ MMA | Iron def → microcytic | ↑ Homocysteine + normal MMA = folate deficiency."},
/*79*/ {"q":"A brain structure being observed is named folia. Which of the following parts of the brain is it related to?","o":["Cerebellum","Medulla oblongata","Hippocampus","Basal ganglia","Pons"],"a":0,"e":"Folia are leaf-like folds on the cerebellar cortex (analogous to gyri on cerebral cortex); increase the surface area of cerebellum. Cerebellum has three layers: molecular, Purkinje, and granular.<br><br>Take Notes: Gyri → cerebral cortex | Lobules → cerebellar hemispheres | Folia = cerebellum (leaf-like)."},
/*80*/ {"q":"A 62-year-old man presents with worsening hand tremors and difficulty performing precise movements. On examination, his hand tremor worsens as his hand approaches a target, and he displays an unsteady gait. Which brain structure is most likely involved in this patient's symptoms?","o":["Basal ganglia","Cerebellum","Substantia nigra pars compacta","Motor cortex","Red nucleus"],"a":1,"e":"Intention tremor (worse on movement toward target) and ataxic gait are cardinal cerebellar signs. Cerebellar lesions impair coordination, balance, and fine motor control — distinct from Parkinson's resting tremor.<br><br>Take Notes: SN pars compacta → Parkinson (resting tremor) | Basal ganglia → tremor at rest | Intention tremor + ataxia = cerebellum."},
/*81*/ {"q":"A 65-year-old man presents with facial puffiness, bruising on the arms, and weakness. He is a smoker and was recently diagnosed with small cell lung carcinoma. Which of the following best explains the facial swelling and bruises on the arms?","o":["Direct tumor invasion of the pituitary gland","SIADH-induced water retention","Tumor secretion of aldosterone","Paraneoplastic hypercalcemia","Paraneoplastic syndrome"],"a":4,"e":"Small cell lung cancer (SCLC) commonly causes paraneoplastic syndromes: ectopic ACTH causing Cushing syndrome (facial puffiness, bruising, easy bruising) and SIADH. Paraneoplastic syndrome encompasses these effects.<br><br>Take Notes: SIADH → hyponatremia (no bruises) | Direct invasion → less common | SCLC + Cushing features = paraneoplastic syndrome."},
/*82*/ {"q":"An elderly patient presented with multiorgan failure. On doing ABGs, the bicarbs were less than normal and CO2 was 65mmHg with overall pH of 7.12. The type of acid-base disorder most likely is:","o":["Metabolic acidosis","Respiratory acidosis","Mixed metabolic and respiratory acidosis","Mixed metabolic and respiratory alkalosis","Metabolic alkalosis with respiratory compensation"],"a":2,"e":"pH 7.12 (acidemia), low HCO3 (metabolic acidosis component), and high PCO2 (respiratory acidosis component instead of expected respiratory compensation with low PCO2) indicates mixed metabolic and respiratory acidosis.<br><br>Take Notes: Pure metabolic acidosis → low PCO2 (compensation) | Mixed → both low HCO3 + high PCO2 | Multiorgan failure = mixed acidosis."},
/*83*/ {"q":"A 30-year-old woman is involved in a posterior hip dislocation after a fall. She complains of pain in the hip and referred pain down the posterior aspect of the thigh and knee. Which nerve is most likely injured?","o":["Femoral nerve","Obturator nerve","Sciatic nerve","Superior gluteal nerve","Tibial nerve"],"a":2,"e":"Posterior hip dislocation classically injures the sciatic nerve as it exits the greater sciatic foramen near the posterior aspect of acetabulum. Refers pain along sciatic distribution — posterior thigh and leg.<br><br>Take Notes: Femoral → anterior thigh | Obturator → medial thigh | Posterior hip dislocation = sciatic."},
/*84*/ {"q":"A child presents with sudden abdominal pain, vomiting, and \"currant jelly\" stools. Which of the following is the most likely diagnosis?","o":["Volvulus","Hirschsprung disease","Meckel diverticulum","Intussusception","Appendicitis"],"a":3,"e":"Intussusception (telescoping of bowel into adjacent segment) in young children: classic triad of colicky abdominal pain, palpable sausage mass, and red currant jelly stools. Ileocolic typical; most common 6-36 months.<br><br>Take Notes: Meckel → painless bleeding | Hirschsprung → no stools (delayed meconium) | Currant jelly stool = intussusception."},
/*85*/ {"q":"During a gastroesophagectomy for esophageal carcinoma, the surgeon must mobilize part of the stomach for reconstruction. Which artery is typically mobilized during mobilization of the greater curvature of the stomach?","o":["Left gastric artery","Short gastric artery","Left gastroepiploic artery","Right gastroepiploic artery","Right gastric artery"],"a":3,"e":"Right gastroepiploic artery (from gastroduodenal) runs along greater curvature and is preserved as the main blood supply to the gastric conduit during esophagectomy; left gastroepiploic mobilized away.<br><br>Take Notes: Left gastric → preserved (lesser curvature) | Short gastrics → divided | Gastric conduit = right gastroepiploic."},
/*86*/ {"q":"In another patient undergoing esophageal reconstruction, a portion of the stomach is mobilized and brought upward to replace the resected esophagus. Which artery must be preserved to maintain the blood supply to the gastric conduit?","o":["Left gastric artery","Left gastroepiploic artery","Right gastric artery","Right gastroepiploic artery","Short gastric arteries"],"a":3,"e":"Right gastroepiploic artery is the principal preserved blood supply to the gastric conduit during esophagectomy; arises from gastroduodenal and courses along greater curvature. Critical to avoid anastomotic ischemia.<br><br>Take Notes: Left gastric → ligated for mobilization | Short gastrics → divided | Gastric conduit blood supply = right gastroepiploic."},
/*87*/ {"q":"A 27-year-old man ingests large amounts of ammonium hydroxide daily for 2 weeks as part of a misguided home remedy. He presents with confusion, muscle cramps, and arrhythmia. Which acid-base disturbance is most likely present?","o":["Metabolic acidosis","Respiratory acidosis","Metabolic alkalosis","Respiratory alkalosis","Mixed metabolic and respiratory acidosis"],"a":2,"e":"Ingestion of ammonium hydroxide (alkaline) causes metabolic alkalosis with hypokalemia (from cellular shift). Symptoms: confusion, muscle cramps, arrhythmia from electrolyte disturbances and pH elevation.<br><br>Take Notes: NH4OH = alkali | Vomiting → metabolic alkalosis (HCl loss) | Alkali ingestion = metabolic alkalosis."},
/*88*/ {"q":"A 12-year-old boy presents with fever, joint pain, and chest discomfort. Two weeks ago, he had a sore throat that resolved without treatment. On examination, his left knee is swollen, warm, and tender. ESR is 70 mm/hr. Most likely diagnosis?","o":["Rheumatoid arthritis","Rheumatic fever","Reactive arthritis","Septic arthritis","Osteomyelitis"],"a":1,"e":"Rheumatic fever follows untreated Group A strep pharyngitis 2-4 weeks later. JONES criteria: Joint (migratory polyarthritis), Carditis, Subcutaneous nodules, Erythema marginatum, Sydenham chorea. Confirms diagnosis with major + minor criteria.<br><br>Take Notes: Reactive arthritis → GU/GI infection trigger | Septic → fever spike, joint culture | Post-strep + carditis = rheumatic fever."},
/*89*/ {"q":"A 55-year-old man develops acute shortness of breath and pleuritic chest pain. Oxygen saturation is 84% on room air. CT pulmonary angiography reveals a large pulmonary embolism. Which of the following is the most important initial step to stabilize this patient's ventilation-perfusion mismatch?","o":["Embolectomy","Oxygen therapy","Systemic fibrinolysis","Heparin infusion","Mechanical ventilation"],"a":1,"e":"Massive PE: initial step is oxygen therapy to correct hypoxemia and V/Q mismatch. Hemodynamic instability warrants thrombolytic or embolectomy after airway stabilization. Anticoagulation prevents propagation.<br><br>Take Notes: Embolectomy → surgical, last resort | Thrombolysis → hemodynamic instability | Initial stabilization = oxygen therapy."},
/*90*/ {"q":"A patient is evaluated for persistent polyuria despite administration of desmopressin. Laboratory testing shows markedly dilute urine. A defect in urea reabsorption is suspected. Which part of the nephron is most likely affected?","o":["Proximal convoluted tubule","Thick ascending limb of loop of Henle","Distal convoluted tubule","Medullary collecting duct","Cortical collecting duct"],"a":3,"e":"Medullary collecting duct is the major site of urea reabsorption (recycling); urea contributes to medullary osmotic gradient via urea transporters (UT-A1, UT-A3). Defects cause inability to concentrate urine.<br><br>Take Notes: Cortical CD → minimal urea | PCT → glucose, sodium | Urea reabsorption = medullary collecting duct."},
/*91*/ {"q":"Parathyroid hormone acts directly on the kidney and bone. Which of the following is a secondary action of PTH?","o":["Phosphaturia","Increased intestinal calcium absorption via vitamin D activation","Increased renal phosphate reabsorption","Direct stimulation of osteoblast collagen production","Decreased renal calcium reabsorption"],"a":1,"e":"PTH indirectly increases intestinal calcium absorption by activating 1α-hydroxylase in kidney to produce active 1,25-(OH)2 vitamin D (calcitriol), which then promotes gut Ca²⁺ absorption.<br><br>Take Notes: Direct PTH → bone resorption + renal Ca²⁺ reabsorption + phosphaturia | Secondary action = vitamin D activation + intestinal Ca²⁺."},
/*92*/ {"q":"A biopsy from a patient with oral leukoplakia shows thickening of the spinous cell layer of the oral epithelium. This histopathologic finding is known as acanthosis. Which epithelial layer is primarily involved?","o":["Stratum basale","Stratum spinosum","Stratum corneum","Stratum granulosum","Stratum lucidum"],"a":1,"e":"Acanthosis = thickening of the stratum spinosum (prickle cell layer); seen in psoriasis, lichen simplex chronicus, leukoplakia. Distinct from hyperkeratosis (stratum corneum) or parakeratosis.<br><br>Take Notes: Hyperkeratosis → stratum corneum | Parakeratosis → retained nuclei in keratin | Acanthosis = stratum spinosum."},
/*93*/ {"q":"A 42-year-old office worker presents with generalized fatigue and darkened skin folds on the back of his neck. BMI is 33 kg/m². Which of the following is the most appropriate initial investigation to assess for the most likely underlying disorder?","o":["Fasting lipid profile","Serum cortisol","Complete blood count","Liver function tests","Oral glucose tolerance test"],"a":4,"e":"Acanthosis nigricans + obesity suggests insulin resistance/type 2 diabetes. OGTT is the most appropriate initial test to detect hyperglycemia and impaired glucose tolerance; HbA1c is alternative.<br><br>Take Notes: Acanthosis nigricans → insulin resistance, also internal malignancy | Cortisol → for Cushing | Insulin resistance screen = OGTT."},
/*94*/ {"q":"A 26-year-old woman presents with severe acne, excessive facial hair, and irregular menstrual cycles. BMI is 30 kg/m². Ultrasound reveals bilaterally enlarged ovaries with multiple peripheral cysts. Which of the following is the most appropriate diagnostic criterion for polycystic ovary syndrome in this patient?","o":["Oligomenorrhea and hirsutism","Hirsutism alone","Elevated CA 125 levels","Ultrasound findings","Weight gain and acne"],"a":0,"e":"Rotterdam criteria for PCOS: need 2 of 3 — (1) oligo/anovulation (irregular cycles), (2) clinical/biochemical hyperandrogenism (hirsutism, acne), (3) polycystic ovaries on US. Oligomenorrhea + hirsutism meets criteria.<br><br>Take Notes: Single criterion → not sufficient | All 3 → most severe phenotype | Best 2-criterion combination = oligo + hirsutism."},
/*95*/ {"q":"During laparoscopy for acute abdominal pain in a woman mid-cycle, a hemorrhagic structure is found on the ovary. Which of the following is the most likely diagnosis?","o":["Corpus luteum","Follicular cyst","Corpus hemorrhagicum","Endometrioma","Theca lutein cyst"],"a":2,"e":"Corpus hemorrhagicum: immediately after ovulation, the ruptured follicle fills with blood forming a hemorrhagic structure on the ovary. Becomes corpus luteum within hours-days as luteinization proceeds.<br><br>Take Notes: Corpus luteum → late, yellow | Follicular cyst → unruptured | Mid-cycle hemorrhagic ovary = corpus hemorrhagicum."},
/*96*/ {"q":"A 48-year-old woman presents with hypertension and hypokalemia. CT scan reveals a well-circumscribed mass in the adrenal gland. Which adrenal zone is most likely responsible for this patient's symptoms?","o":["Zona reticularis","Zona fasciculata","Zona glomerulosa","Adrenal medulla","Adrenal Cortex"],"a":2,"e":"Conn syndrome (primary aldosteronism): aldosterone-secreting adenoma in zona glomerulosa causes hypertension, hypokalemia, metabolic alkalosis. Zona glomerulosa produces mineralocorticoids (aldosterone).<br><br>Take Notes: Fasciculata → cortisol (glucocorticoids) | Reticularis → androgens | Medulla → catecholamines | Aldosterone = zona glomerulosa."},
/*97*/ {"q":"Type of necrosis in omentum (mesentery in pancreatitis):","o":["Gangrenous necrosis","Caseous necrosis","Liquefactive necrosis","Fat necrosis","Traumatic necrosis"],"a":3,"e":"Acute pancreatitis: released lipase hydrolyses triglycerides in mesenteric/omental fat producing fat necrosis. Free fatty acids precipitate with calcium forming chalky white deposits (saponification).<br><br>Take Notes: Coagulative → solid organs (heart, kidney) | Caseous → TB | Pancreatitis omentum = fat necrosis."},
/*98*/ {"q":"A patient has been diagnosed with salpingitis. The structure/organ involved in this inflammation has which of the following types of epithelium?","o":["Simple columnar epithelium","Simple columnar ciliated epithelium","Simple cuboidal epithelium","Stratified squamous epithelium","Stratified columnar ciliated"],"a":1,"e":"Fallopian tube (salpingitis = inflammation of fallopian tube) is lined by simple columnar ciliated epithelium with peg cells. Cilia transport ovum toward uterus; loss leads to infertility and ectopic pregnancy.<br><br>Take Notes: Vagina → stratified squamous | Cervix → simple columnar | Fallopian tube = simple columnar ciliated."},
/*99*/ {"q":"Patient post thyroidectomy has hypoparathyroidism. Most likely electrolyte abnormality found in this patient would be:","o":["Hypercalcemia","Hypokalemia","Hypopituitarism","Hypocalcemia","Hypophosphatemia"],"a":3,"e":"Post-thyroidectomy hypocalcemia occurs when parathyroid glands are inadvertently devascularized or removed; loss of PTH causes hypocalcemia (low bone resorption, less Ca²⁺ reabsorption) with hyperphosphatemia.<br><br>Take Notes: Hypoparathyroidism → low Ca²⁺ + high PO4³⁻ | Hypercalcemia → opposite (hyperparathyroid) | Post-thyroidectomy = hypocalcemia."},
/*100*/ {"q":"Angle of the rib is related to which of the following?","o":["Shaft","Head","Neck","Costal cartilage","Tubercle"],"a":0,"e":"The angle of the rib is the most posterior part of the shaft where the rib changes direction (curves anteriorly). It is the strongest point and most common site of fracture.<br><br>Take Notes: Head → articulates with vertebra | Neck → between head + tubercle | Angle = on rib shaft (posterior)."},
/*101*/ {"q":"A 64-year-old man presents with jaundice, pale stools, and dark urine. Ultrasound reveals a gallstone lodged in the distal common bile duct causing extrahepatic biliary obstruction. In addition to elevated conjugated bilirubin, which of the following laboratory findings would support the diagnosis?","o":["Elevated alanine aminotransferase (ALT)","Elevated alkaline phosphatase (ALP)","Elevated unconjugated bilirubin","Low gamma glutamyl transferase (GGT)","Decreased Hepcidin"],"a":1,"e":"Cholestatic (obstructive) jaundice: elevated ALP (>3x normal) and GGT indicate biliary obstruction; conjugated hyperbilirubinemia, dark urine, pale stools. ALT/AST less elevated than in hepatocellular injury.<br><br>Take Notes: ALT/AST → hepatocellular injury | Unconjugated bili → hemolysis | Obstructive jaundice = ALP elevation."},
/*102*/ {"q":"A 19-year-old college student presents with headache and low-grade fever for 3 days. Lumbar puncture reveals clear cerebrospinal fluid with normal glucose, mildly elevated protein, 1 red blood cell/μL, and a predominance of lymphocytes. Which of the following is the most likely etiology?","o":["Haemophilus influenzae","Influenza virus","Neisseria meningitidis","Listeria monocytogenes","Proteus mirabilis"],"a":1,"e":"Viral (aseptic) meningitis: clear CSF, normal glucose, mildly elevated protein, lymphocytic predominance. Viruses (enterovirus, mumps, HSV, influenza) cause this picture. Bacterial would show neutrophils, low glucose.<br><br>Take Notes: Bacterial meningitis → neutrophils, low glucose | TB → very low glucose | Aseptic + lymphocytes = viral (e.g., influenza)."},
/*103*/ {"q":"A 58-year-old man with type 2 diabetes mellitus presents with sweating, tremors, and confusion. His medications include metformin and another oral drug. Laboratory testing confirms hypoglycemia. Which of the following drugs is the most likely cause?","o":["Sulfonylureas","Metformin","Acarbose","Pioglitazone","Insulin"],"a":0,"e":"Sulfonylureas (glipizide, glimepiride, glyburide) stimulate insulin secretion from pancreatic β-cells regardless of glucose level, commonly causing hypoglycemia — especially with skipped meals or in elderly.<br><br>Take Notes: Metformin → no hypoglycemia | Acarbose → no hypoglycemia (alpha-glucosidase) | Hypoglycemia oral antidiabetic = sulfonylurea."},
/*104*/ {"q":"A 72-year-old man presents with progressive urinary hesitancy and nocturia. Digital rectal examination reveals an asymmetrically enlarged, firm, and nodular prostate. His PSA level is 49 ng/mL. Which of the following is the most likely diagnosis?","o":["Benign prostatic hyperplasia","Acute bacterial prostatitis","Prostatic adenocarcinoma","Chronic prostatitis","Pyelonephritis"],"a":2,"e":"Prostatic adenocarcinoma: PSA >40 ng/mL with hard, nodular, asymmetric prostate on DRE strongly suggests malignancy. BPH typically has symmetric firm enlargement with PSA usually <10 ng/mL.<br><br>Take Notes: BPH → smooth, symmetric, PSA <10 | Bacterial prostatitis → tender + fever | Nodular hard prostate + PSA 49 = adenocarcinoma."},
/*105*/ {"q":"A 68-year-old man presents with urinary frequency and hesitancy. Examination and imaging confirm benign prostatic hyperplasia. Which of the following zones of the prostate is most commonly involved in this condition?","o":["Peripheral zone","Transitional zone","Central zone","Anterior fibromuscular stroma","Acinus"],"a":1,"e":"Benign prostatic hyperplasia (BPH) arises in the transitional zone (periurethral); enlargement compresses prostatic urethra causing urinary obstruction. Peripheral zone is the site of prostate cancer.<br><br>Take Notes: Peripheral zone → prostate cancer (most common site) | Central zone → 25% gland | BPH = transitional zone."},
/*106*/ {"q":"The structurally largest lobe of prostate is:","o":["Peripheral","Central gland","Median lobe","Lateral lobe","Median lobe and central gland"],"a":0,"e":"The peripheral zone is the largest part of the prostate (~70% of glandular tissue); located posteriorly. Most adenocarcinomas (>70%) arise here, palpable on digital rectal examination.<br><br>Take Notes: Transitional → BPH | Central → 25% | Anterior fibromuscular → no glands | Largest zone = peripheral."},
/*107*/ {"q":"A 34-year-old woman with an intrauterine device presents with lower abdominal pain and fever. Pelvic examination reveals mucopurulent discharge. Gram stain of the exudate shows basophilic colonies. Which of the following organisms is the most likely cause?","o":["Actinomyces israelii","Staphylococcus aureus","Escherichia coli","Neisseria gonorrhoeae","Listeria monocytogenes"],"a":0,"e":"Actinomyces israelii: anaerobic gram-positive filamentous bacteria; commonly associated with IUD-related pelvic infections (\"sulfur granules\" in discharge). Causes chronic indolent infection with draining sinuses.<br><br>Take Notes: N. gonorrhoeae → gram-negative diplococci | Staph aureus → grape-like cocci | IUD-related PID = Actinomyces."},
/*108*/ {"q":"A 59-year-old man with issues where he can follow commands and understands speech, but has difficulty forming words. Which of the following cortical areas is most likely affected?","o":["Broca's area","Wernicke's area","Angular gyrus","Primary auditory cortex","Arcuate fasciculus"],"a":0,"e":"Broca aphasia (expressive/motor aphasia): patient understands language and follows commands but cannot fluently produce speech; word-finding difficulty. Broca area in inferior frontal gyrus of dominant hemisphere.<br><br>Take Notes: Wernicke → fluent but no comprehension | Conduction → arcuate fasciculus | Cannot form words but comprehends = Broca."},
/*109*/ {"q":"A 62-year-old woman presents with fluent but nonsensical speech following a stroke. She is unaware of her language deficit and is unable to follow verbal commands. Which of the following cortical regions is most likely involved?","o":["Broca's area","Wernicke's area","Supplementary motor cortex","Primary motor cortex","Angular gyrus"],"a":1,"e":"Wernicke aphasia (receptive aphasia): fluent but nonsensical speech, impaired comprehension, anosognosia (unaware of deficit). Wernicke area in posterior superior temporal gyrus of dominant hemisphere.<br><br>Take Notes: Broca → non-fluent expression | Conduction → arcuate fasciculus | Fluent nonsensical + no comprehension = Wernicke."},
/*110*/ {"q":"A 34-year-old man with hypotension following trauma was administered ketamine for anesthesia induction. Which of the following best explains the choice of this drug?","o":["It increases sympathetic stimulation and blood pressure","It produces cardiac depression","It causes profound vasodilation","It suppresses adrenal function","It has rapid onset and short duration"],"a":0,"e":"Ketamine causes sympathomimetic effects (catecholamine release), increasing heart rate, blood pressure, and cardiac output. Useful for shock/trauma patients with hypotension; also provides dissociative anesthesia.<br><br>Take Notes: Propofol/etomidate → cardiac depression | Ketamine = sympathetic stimulation + BP rise."},
/*111*/ {"q":"A 25-year-old man experiences lightheadedness upon standing. His supine blood pressure is 110/70 mmHg with a heart rate of 72/min. On standing, his blood pressure drops to 90/60 mmHg and heart rate rises to 100/min. Which of the following best explains the increase in heart rate?","o":["Decreased peripheral resistance","Decreased venous return","Increased cardiac output","Increased stroke volume","Increase cardiac force of contraction"],"a":1,"e":"Orthostatic hypotension: standing reduces venous return (pooling in legs); baroreceptor reflex activated; sympathetic outflow increases heart rate to compensate. Reduced cardiac output triggers compensatory tachycardia.<br><br>Take Notes: Postural change → venous pooling | Baroreceptor → sympathetic activation | Standing tachycardia = decreased venous return."},
/*112*/ {"q":"A 58-year-old smoker is found to have a lung mass. Biopsy reveals small cells arranged in sheets. Which paraneoplastic syndrome is most likely associated with this tumor?","o":["SIADH","Hypercalcemia","Cushing syndrome due to ACTH","Hypokalemia due to renin secretion","Hyperthyroidism"],"a":0,"e":"Small cell lung carcinoma (SCLC) paraneoplastic syndromes: SIADH (ectopic ADH), Cushing (ectopic ACTH), and Lambert-Eaton myasthenic syndrome. SIADH causes hyponatremia from inappropriate water retention.<br><br>Take Notes: Hypercalcemia → squamous cell lung CA (PTHrP) | SCLC = SIADH + ectopic ACTH + LEMS."},
/*113*/ {"q":"A 40-year-old man is rear-ended in a motor vehicle collision while stationary at a traffic light. He experiences immediate neck pain and restricted neck movement. Which of the following is the most likely mechanism of injury?","o":["Hyperextension injury","Hyperflexion injury","Axial compression injury","Rotational injury","Thoracic flexion injury"],"a":0,"e":"Whiplash injury (rear-end collision): head and neck thrown into sudden hyperextension followed by flexion. Sprains cervical paraspinal muscles, ligaments. Symptoms develop within 24-48 hours.<br><br>Take Notes: Hyperflexion → forward impact | Axial compression → falls | Rear-end collision = hyperextension."},
/*114*/ {"q":"A 24-year-old man sustains a supracondylar fracture of the femur with posterior displacement of the distal fragment. Which of the following structures lies deepest and is most at risk for injury in the popliteal fossa?","o":["Tibial nerve","Popliteal vein","Popliteal artery","Common peroneal nerve","Popliteus tendon"],"a":2,"e":"Popliteal artery is the deepest (most anterior) structure in the popliteal fossa, lying directly on the femur posteriorly; supracondylar femur fractures with posterior displacement classically tear popliteal artery.<br><br>Take Notes: Tibial nerve → most superficial | Popliteal vein → middle | Deepest popliteal fossa = popliteal artery."},
/*115*/ {"q":"A fisherman presents with perifollicular hemorrhages, ecchymoses, and bleeding gums. Which deficiency is the most likely cause?","o":["Vitamin A","Vitamin C","Vitamin K","Vitamin D","Vitamin E"],"a":1,"e":"Scurvy (vitamin C deficiency): perifollicular hemorrhages (corkscrew hairs), ecchymoses, bleeding gums, poor wound healing. Vitamin C needed for collagen hydroxylation (proline, lysine); deficiency causes defective collagen.<br><br>Take Notes: Vitamin K def → bleeding without follicular changes | Vitamin A → night blindness | Perifollicular hemorrhage + gum bleeding = scurvy."},
/*116*/ {"q":"A 6-week pregnant woman with hyperthyroidism is taking methimazole. Her laboratory tests show TSH at the lower limit of normal and T4/T3 at pre-pregnancy levels. Which of the following is the best next step?","o":["Immediately switch to propylthiouracil","Increase methimazole dose","Continue current dose of methimazole","Discontinue antithyroid therapy","Add Propylthiouracil while increasing methimazole dose"],"a":0,"e":"Methimazole is teratogenic (aplasia cutis, choanal atresia) in first trimester; switch to PTU until end of first trimester, then can switch back to methimazole if needed. PTU has hepatotoxicity risk.<br><br>Take Notes: PTU = first trimester preferred | Methimazole = 2nd/3rd trimester preferred (PTU hepatotoxicity) | 6-week pregnancy + methimazole = switch to PTU."},
/*117*/ {"q":"A 45-year-old man on ciprofloxacin therapy for prostatitis develops decreased urine output after 2 days. To evaluate for drug toxicity, when should serum drug levels be measured?","o":["Immediately send blood drug levels","2 hours after the next dose","1 hour after the next dose","At steady state","After 1 half life of the drug"],"a":3,"e":"Therapeutic drug monitoring should be done at steady state (after ~5 half-lives of the drug); this gives accurate plasma concentration reflecting clinical levels. Earlier sampling gives misleading subtherapeutic levels.<br><br>Take Notes: Peak levels → maximum effect | Trough → before next dose | Drug toxicity evaluation = at steady state."},
/*118*/ {"q":"Regarding corpus callosum:","o":["Attaches similar areas of the cerebral hemispheres","Genu moves anteriorly to form body","Abducent nerve lies in the roof of corpus","It consists of white matter composed of projection fibres","It contains gray matter only"],"a":0,"e":"Corpus callosum is the largest commissural fiber tract; connects homologous (similar) areas of the two cerebral hemispheres, allowing interhemispheric communication. Consists of white matter (commissural, not projection, fibers).<br><br>Take Notes: Composed of commissural fibers (not projection) | Genu → anterior end | Corpus callosum = connects similar cortical areas."},
/*119*/ {"q":"You're observing stomach antrum; at the end of the antrum, all the muscles come together sharply. You're looking at what structure?","o":["Incisura angularis","Pylorus","Cardiac notch","Lesser curvature","Aortic notch"],"a":1,"e":"The pylorus is the distal gastric outlet where smooth muscle thickens to form the pyloric sphincter; controls gastric emptying. Hypertrophic pyloric stenosis affects this in infants.<br><br>Take Notes: Incisura angularis → angular notch on lesser curvature | Cardiac notch → upper junction | Gastric outlet muscle convergence = pylorus."},
/*120*/ {"q":"A 38-year-old man presents with severe epigastric pain that begins 2 hours after meals and is worse at night. Which of the following is the most likely diagnosis?","o":["Duodenal ulcer","Gastric ulcer","Peptic ulcer","Gastritis","GERD"],"a":0,"e":"Duodenal ulcer pain: 2-3 hours after meals (pain when stomach is empty) and at night (acid secretion peaks). Relieved by food/antacids. H. pylori infection in ~95% of cases.<br><br>Take Notes: Gastric ulcer → pain WORSE with meals | GERD → retrosternal burning | Pain 2h after meals + night = duodenal ulcer."},
/*121*/ {"q":"A 46-year-old woman takes an unknown herbal medication for weight loss. She develops 15 episodes of vomiting in one day, with the last 2 episodes containing bright red blood. Most likely diagnosis?","o":["Mallory-Weiss tear","Peptic ulcer disease","Esophageal varices","Boerhaave syndrome","Choristoma"],"a":0,"e":"Mallory-Weiss tear: longitudinal mucosal tear at gastroesophageal junction from repeated forceful vomiting; causes hematemesis with fresh red blood after multiple episodes of vomiting (\"vomiting then bleeding\" history).<br><br>Take Notes: Boerhaave → full thickness rupture (mediastinitis) | Varices → portal hypertension | Vomiting then bleeding = Mallory-Weiss tear."},
/*122*/ {"q":"A 40-year-old man dies suddenly. Autopsy reveals multiple cystic dilatations in both kidneys. His father also died from kidney disease in his 50s. Which of the following is the most likely pattern of inheritance?","o":["Autosomal recessive","Autosomal dominant","X-linked recessive","Mitochondrial inheritance","Acquired disorder"],"a":1,"e":"Adult-type Polycystic Kidney Disease (ADPKD): autosomal dominant (PKD1 chromosome 16 most common, PKD2 chromosome 4); bilateral renal cysts, hypertension, berry aneurysms, hepatic cysts. Presents in adults 30-50s.<br><br>Take Notes: ARPKD → infants/children, autosomal recessive | ADPKD = autosomal dominant adult-onset."},
/*123*/ {"q":"Female with hot flashes and amenorrhea for one year. Which of the following hormones is increased in the blood?","o":["Testosterone","TSH","FSH","Estrogen","Estriol"],"a":2,"e":"Menopause: ovarian follicle depletion causes low estrogen feedback; hypothalamic-pituitary axis responds with elevated FSH (>30-40 IU/L). LH also rises but less than FSH. FSH/LH inversion is hallmark.<br><br>Take Notes: TSH → unrelated | Testosterone → mildly increased relatively | Menopause biochemical hallmark = elevated FSH."},
/*124*/ {"q":"A patient, 52 y/o presented with painful knee joint and red base of the big toe with swelling. He has had similar episodes in the past. Which of the following is the confirmatory test for the diagnosis of gout?","o":["Synovial fluid urate crystals","Serum uric acid","Urine urate levels","X-ray of the joint","Gram staining of the joint aspirate"],"a":0,"e":"Gout: synovial fluid aspiration showing negatively birefringent needle-shaped monosodium urate crystals under polarized light is gold standard for diagnosis. Serum uric acid can be normal during acute attack.<br><br>Take Notes: Serum uric acid → supportive but normal in 30% acute | X-ray → late findings | Gout confirmation = synovial fluid urate crystals."},
/*125*/ {"q":"A child presented with complaints of having urine with a specific odor of maple syrup. Which of the following is the underlying cause?","o":["Alkaptonuria","Branched chain ketoaciduria","Urobilinogen in the urine","Sterile pyuria","Hemophilia"],"a":1,"e":"Maple syrup urine disease (MSUD): branched-chain α-ketoacid dehydrogenase deficiency; accumulation of leucine, isoleucine, valine causes characteristic maple syrup-smelling urine, neurological deterioration, and seizures.<br><br>Take Notes: Alkaptonuria → black urine (homogentisic acid) | PKU → mousy odor | Maple syrup urine = branched-chain ketoaciduria."},
/*126*/ {"q":"A 29-year-old man sustains blunt trauma to the lateral chest wall in a motor vehicle accident. He later develops shortness of breath, and chest imaging reveals herniation of abdominal contents into the thoracic cavity. The defect is located in the posterolateral aspect of the diaphragm. Through which of the following anatomic areas did the herniation most likely occur?","o":["Central tendon","Lumbocostal triangle (Bochdalek's area)","Pleuroperitoneal canal","Caval opening","Sternocostal hiatus"],"a":1,"e":"Bochdalek hernia: posterolateral diaphragmatic defect (lumbocostal triangle) — failed closure of pleuroperitoneal membrane. Most common congenital diaphragmatic hernia (90%), usually left-sided. Acquired form from trauma.<br><br>Take Notes: Morgagni → anteromedial (sternocostal) | Hiatus hernia → esophageal opening | Posterolateral = Bochdalek (lumbocostal triangle)."},
/*127*/ {"q":"In a young adult, diagnosis of Klinefelter is made. For absolute confirm diagnosis, which is gold standard?","o":["Genetic Analysis","FSH and LH","Testosterone","U/S Testes","Enzymatic assay"],"a":0,"e":"Klinefelter syndrome (47,XXY): genetic analysis (karyotyping) is the gold standard for confirmation. FSH/LH elevated, testosterone may be low/normal. Karyotype is definitive diagnostic test.<br><br>Take Notes: FSH/LH → supportive (raised) | Testosterone → variable | Klinefelter confirmation = karyotype (genetic analysis)."},
/*128*/ {"q":"A 9-year-old child presents with hearing loss in the right ear. Otoscopic examination shows a retracted tympanic membrane. Which of the following is the most likely cause?","o":["Chronic suppurative otitis media","Blockage of the Eustachian tube","Otosclerosis","Labyrinthitis","Vestibular neuritis"],"a":1,"e":"Eustachian tube dysfunction (blockage) creates negative middle ear pressure, retracting the tympanic membrane and causing conductive hearing loss. Common in children due to short, horizontal Eustachian tubes.<br><br>Take Notes: CSOM → perforated TM with discharge | Otosclerosis → in adults, fixed stapes | Retracted TM + hearing loss = Eustachian tube blockage."},
/*129*/ {"q":"A 28-year-old woman in her second trimester of pregnancy is diagnosed with pyelonephritis. She has no known drug allergies. Which of the following antibiotics is safest to use in this patient?","o":["Ceftriaxone","Ciprofloxacin","Doxycycline","Gentamicin","Cefoperazone"],"a":0,"e":"Ceftriaxone (3rd generation cephalosporin) is safe in pregnancy (category B) and effective for pyelonephritis. Ciprofloxacin (cartilage), doxycycline (teeth), and gentamicin (nephrotoxicity) are avoided in pregnancy.<br><br>Take Notes: Ciprofloxacin → cartilage damage | Doxycycline → yellow teeth | Pregnancy + pyelonephritis = ceftriaxone."},
/*130*/ {"q":"A 26-year-old female athlete collapses during a long-distance run. She regains consciousness within minutes and reports chest discomfort and dizziness before the episode. She has already been diagnosed with aortic stenosis. Which of the following is the most likely cause of her collapse?","o":["Narrow pulse pressure","Hypertrophic obstructive cardiomyopathy","Pulmonary embolism","Mitral valve prolapse with regurgitation","Arrhythmogenic right ventricular cardiomyopathy"],"a":0,"e":"Aortic stenosis: fixed cardiac output during exercise causes inability to meet demand; narrow pulse pressure and reduced cerebral perfusion lead to exertional syncope. Classic triad: angina, syncope, heart failure (SAD).<br><br>Take Notes: HCM → similar but different etiology | PE → pleuritic chest pain | AS-related syncope = narrow pulse pressure (exertional)."},
/*131*/ {"q":"A laboratory testing of a patient suggests pyruvate carboxylase deficiency. Which of the following cofactors is essential for the enzyme deficient in this patient?","o":["Biotin","Thiamine pyrophosphate","FAD","D. NAD+","Pyridoxal phosphate"],"a":0,"e":"Pyruvate carboxylase (mitochondrial enzyme converting pyruvate to oxaloacetate for gluconeogenesis) requires biotin as cofactor. Other biotin-dependent enzymes: acetyl-CoA carboxylase, propionyl-CoA carboxylase.<br><br>Take Notes: Pyruvate dehydrogenase → TPP (B1) | PDH complex → FAD (riboflavin) | Pyruvate carboxylase = biotin cofactor."},
/*132*/ {"q":"A 65-year-old man with a recent history of hip fracture surgery presents with sudden shortness of breath and pleuritic chest pain. His oxygen saturation is 86%. CT pulmonary angiography confirms a pulmonary embolism. The most likely source of the embolus is:","o":["Pulmonary artery","Femoral vein","Inferior vena cava","Popliteal veins","Great saphenous vein"],"a":1,"e":"Hip fracture surgery: major risk for DVT in pelvis and lower limb deep veins. Femoral vein is the most common source of clinically significant PE due to large vein with high flow.<br><br>Take Notes: Calf veins → small PEs (less significant) | IVC → systemic source | Hip surgery DVT/PE = femoral vein."},
/*133*/ {"q":"A 45-year-old woman presents with fatigue, weight gain, constipation, and increased sensitivity to cold over the past several months. On examination, she has dry skin, coarse hair, and a puffy face. Which of the following is the most likely diagnosis?","o":["Hyperthyroidism Primary","Secondary hypothyroidism","Hypothyroidism","Subclinical hyperthyroidism","Hashimoto thyroiditis in hyperthyroid phase"],"a":2,"e":"Primary hypothyroidism: fatigue, weight gain, cold intolerance, constipation, dry skin, myxedema (puffy face), coarse hair. Hashimoto thyroiditis is most common cause in developed countries; lab shows high TSH, low T4.<br><br>Take Notes: Secondary → low TSH from pituitary | Subclinical hyper → low TSH, normal T4 | Cold + weight gain + fatigue = hypothyroidism."},
/*134*/ {"q":"An 8-year-old child is brought to the clinic because of repeated brief episodes during class in which he suddenly stops talking, stares blankly for about 10 seconds, and then resumes activity without confusion. EEG shows generalized 3-Hz spike-and-wave discharges. Which of the following is the most appropriate first-line therapy that avoids significant sedation?","o":["Diazepam","Phenytoin","Ethosuximide","Carbamazepine","Phenobarbital"],"a":2,"e":"Absence (petit mal) seizures: classic 3-Hz spike-and-wave EEG, brief staring spells without confusion. Ethosuximide is first-line (specific T-type calcium channel blocker) without significant sedation. Valproate alternative.<br><br>Take Notes: Phenytoin/carbamazepine → can worsen absence | Diazepam → not first-line | Absence seizure = ethosuximide."},
/*135*/ {"q":"A young adult presents with a slowly enlarging, painless lump on her forehead that has been present for several months. The mass is soft, mobile, and not attached to the underlying bone or skin. Excisional biopsy shows mature adipocytes. Which of the following is the most likely diagnosis?","o":["Neurofibroma","Lipoma","Sebaceous cyst","Osteoma","Fibrosarcoma"],"a":1,"e":"Lipoma: benign tumor of mature adipocytes; soft, mobile, painless, not attached to skin or underlying tissue. Most common soft tissue tumor in adults. Usually solitary; complete excision is curative.<br><br>Take Notes: Sebaceous cyst → attached to skin, with punctum | Neurofibroma → painful, neural | Soft mobile + adipocytes = lipoma."},
/*136*/ {"q":"A 34-year-old man presents with a swelling on the dorsum of his right hand, which becomes more prominent when the wrist is flexed. The mass is fluctuant and transilluminates. Which of the following is the most likely diagnosis?","o":["Epidermal inclusion cyst","Ganglion cyst","Lipoma","Synovial sarcoma","Hemangioma"],"a":1,"e":"Ganglion cyst: fluid-filled mucinous cyst arising from tendon sheath or joint capsule; typically on dorsal wrist, becomes more prominent on flexion, transilluminates. Most common soft tissue mass of hand/wrist.<br><br>Take Notes: Lipoma → doesn't transilluminate | Epidermal cyst → cheesy contents | Dorsal wrist + transilluminates + flexion = ganglion cyst."},
/*137*/ {"q":"A physician is conducting a clinical trial and ensures that participants are fully informed about the study's risks, benefits, and alternatives before obtaining their consent. This ethical practice primarily upholds which of the following principles?","o":["Beneficence","Fidelity","Justice","Non-maleficence","Autonomy"],"a":4,"e":"Autonomy: respect for the patient's right to make informed decisions about their own care or research participation. Informed consent embodies autonomy — providing full information about risks, benefits, and alternatives.<br><br>Take Notes: Beneficence → doing good | Non-maleficence → avoiding harm | Justice → fairness | Informed consent = autonomy."},
/*138*/ {"q":"A patient diagnosed with a chronic illness begins volunteering at a community support center, helping others with similar conditions. He reports that this activity improves his own mood and sense of purpose. Which of the following best describes his behavior?","o":["Projection","Reaction formation","Sublimation","Altruism","Displacement"],"a":3,"e":"Altruism (mature defense mechanism): converting one's own difficulties into helping others; provides meaning and benefits self and others. A healthy adaptive coping mechanism.<br><br>Take Notes: Sublimation → channeling impulses to acceptable acts | Reaction formation → opposite feelings | Helping others to cope = altruism."},
/*139*/ {"q":"A 58-year-old man with type 2 diabetes is brought to the emergency department after being found unconscious at home. Paramedics note generalized tonic-clonic movements en route. His medications include an oral antidiabetic drug. Laboratory testing shows glucose of 38 mg/dL. Which of the following is the most likely explanation for his seizure?","o":["Lactic acidosis","Hypoglycemia","Hyperosmolar hyperglycemic state","Ketoacidosis","Electrolyte disturbance from dehydration"],"a":1,"e":"Severe hypoglycemia (glucose 38 mg/dL) is a common cause of seizures and altered mental status in diabetic patients on sulfonylureas or insulin; neuroglycopenia causes neurological dysfunction including seizures.<br><br>Take Notes: HHS → hyperglycemia + dehydration | DKA → ketones, acidosis | Diabetic on oral drug + seizure + glucose 38 = hypoglycemia."},
/*140*/ {"q":"A 48-year-old man with a BMI of 32 kg/m² is newly diagnosed with type 2 diabetes mellitus. His fasting blood glucose is 168 mg/dL. He has no history of renal disease or heart failure. Which of the following is the most appropriate initial pharmacologic treatment?","o":["Metformin","Insulin glargine","Glipizide","Pioglitazone","Acarbose"],"a":0,"e":"Metformin is first-line pharmacologic treatment for type 2 diabetes; reduces hepatic gluconeogenesis (AMPK activation), weight-neutral, no hypoglycemia risk. Add other agents if HbA1c remains uncontrolled.<br><br>Take Notes: Sulfonylureas → 2nd line | Insulin → severe hyperglycemia, failure of orals | Type 2 DM first-line = metformin."},
/*141*/ {"q":"A 36-year-old man sustains a fracture of the proximal humerus and requires shoulder surgery. During the procedure, the surgeon ligates a vessel within the quadrangular space to control bleeding. Which of the following vessels was most likely ligated?","o":["Anterior circumflex humeral artery","Posterior circumflex humeral artery","Thoracoacromial artery","Suprascapular artery","Subscapular artery"],"a":1,"e":"Quadrangular space contents: axillary nerve and posterior circumflex humeral artery. Bordered by teres minor (superior), teres major (inferior), surgical neck of humerus (lateral), long head of triceps (medial).<br><br>Take Notes: Anterior circumflex humeral → near surgical neck | Suprascapular → above scapula | Quadrangular space = axillary nerve + post. circumflex humeral."},
/*142*/ {"q":"The ligamentum teres of the liver is a fibrous remnant of which of the following fetal structures?","o":["Ductus arteriosus","Left umbilical vein","Right umbilical artery","Vitelline duct","Allantois"],"a":1,"e":"Ligamentum teres hepatis (round ligament of liver) is the obliterated left umbilical vein remnant; runs in the free edge of falciform ligament. Carried oxygenated blood from placenta to fetus in utero.<br><br>Take Notes: Ligamentum venosum → ductus venosus | Median umbilical ligaments → urachus | Ligamentum teres = left umbilical vein."},
/*143*/ {"q":"40-year-old man presents with progressive hearing loss in the right ear and occasional dizziness. Neurologic examination reveals mild right facial weakness. Which of the following structures is most likely affected?","o":["Mandible","Internal Acoustic Meatus","Zygoma","Visual Cortex","Jugular Foramen"],"a":1,"e":"Cerebellopontine angle tumor (likely vestibular schwannoma) compressing structures in the internal acoustic meatus: CN VII (facial — weakness) and CN VIII (vestibulocochlear — hearing loss, dizziness).<br><br>Take Notes: Jugular foramen → CN IX, X, XI | CPA tumor → IAM contents | CN VII + VIII = internal acoustic meatus."},
/*144*/ {"q":"A 55-year-old man with a sedentary lifestyle is found to have elevated triglycerides and decreased HDL cholesterol on a routine checkup. His fasting glucose is mildly elevated. Which of the following is most likely responsible for these findings?","o":["Testosterone","Decreased hepatic VLDL synthesis","HMG CoA Lipase","Insulin","Glucagon"],"a":3,"e":"Metabolic syndrome (insulin resistance): elevated insulin (compensatory hyperinsulinemia) increases hepatic VLDL secretion (high TGs) and decreases HDL via increased CETP activity. Central obesity + impaired glucose tolerance.<br><br>Take Notes: Insulin resistance → hyperinsulinemia → high TG + low HDL | Metabolic syndrome biochemical hallmark = insulin (compensatory)."},
/*145*/ {"q":"A 63-year-old man presents with massive upper gastrointestinal bleeding. Endoscopy reveals bleeding in the third part of the duodenum. Which of the following vessels is most likely the source of hemorrhage in this location?","o":["Aorta","Superior mesenteric artery","Inferior mesenteric artery","Gastroduodenal artery","Splenic artery"],"a":1,"e":"Third part of duodenum is crossed anteriorly by superior mesenteric artery (SMA); aortoenteric fistula or SMA syndrome can cause bleeding here. SMA passes between aorta and duodenum at L1-L2.<br><br>Take Notes: Posterior duodenal ulcer (D1) → gastroduodenal artery | D3 region = SMA proximity."},
/*146*/ {"q":"The superior rectal artery, the main arterial supply to the rectum, is a direct branch of which of the following vessels?","o":["Internal iliac artery","Inferior mesenteric artery","Middle sacral artery","Internal pudendal artery","Common iliac artery"],"a":1,"e":"Superior rectal artery is the terminal branch of inferior mesenteric artery (IMA), the main arterial supply to upper rectum. Middle and inferior rectal arteries from internal iliac supply lower rectum.<br><br>Take Notes: Middle rectal → internal iliac | Inferior rectal → internal pudendal | Superior rectal artery = IMA branch."},
/*147*/ {"q":"Fracture of clavicle with backward dislocation of sternoclavicular junction will cause damage to which of the following?","o":["Subclavian vein","Thoracic duct","Common carotid artery","Phrenic nerve","Trachea"],"a":4,"e":"Posterior dislocation of sternoclavicular joint can compress retrosternal structures including trachea, brachiocephalic vessels, and esophagus. Tracheal compression is the most immediately life-threatening complication.<br><br>Take Notes: Subclavian vein → also at risk | Trachea → critical airway compromise | Posterior SC dislocation = tracheal injury."},
/*148*/ {"q":"Bacterial spores can survive extreme heat due to which of the following protective features?","o":["Presence of dipicolinic acid and thick keratin-like coat","Production of thick peptidoglycan cell wall","Active DNA repair enzymes","High metabolic activity","Abundant ribosomes"],"a":0,"e":"Bacterial endospores (Bacillus, Clostridium): contain dipicolinic acid which stabilizes DNA, low water content, thick keratin-like spore coat. Resistant to heat (autoclaving needed), desiccation, chemicals, radiation.<br><br>Take Notes: Vegetative cells → killed by heat | Autoclave 121°C × 15 min → kills spores | Spore resistance = dipicolinic acid + protective coat."},
/*149*/ {"q":"The ossification of the sternum is typically completed by approximately which of the following ages?","o":["12 years","16 years","18 years","25 years","30 years"],"a":3,"e":"Sternum has multiple ossification centers; complete fusion of sternebrae and final ossification is typically completed by ~25 years of age. Manubriosternal joint may remain unfused throughout life.<br><br>Take Notes: Birth → primary centers | Puberty → sternebrae fusion | Sternum complete ossification = ~25 years."},
/*150*/ {"q":"A 42-year-old teacher presents with difficulty producing high-pitched sounds after undergoing thyroid surgery. Which nerve is most likely injured?","o":["Superior laryngeal nerve","Vagus","Recurrent laryngeal nerve","Glossopharyngeal nerve","Phrenic Nerve"],"a":0,"e":"External branch of superior laryngeal nerve supplies cricothyroid muscle (tenses vocal cords for high-pitched sounds); injured at superior thyroid artery ligation. Causes monotone voice and inability to produce high pitch.<br><br>Take Notes: RLN injury → hoarseness (vocal cord paralysis) | Superior laryngeal external branch = high-pitched voice loss (singer's nerve)."},
/*151*/ {"q":"A 58-year-old man with a 10-year history of poorly controlled hypertension undergoes echocardiography which reveals an increased left ventricular wall thickness and mass. Which of the following processes is responsible for this change?","o":["Hyperplasia","Hypertrophy","Metaplasia","Atrophy","Myositis ossificans"],"a":1,"e":"Cardiac myocytes are post-mitotic; in response to chronic pressure overload (hypertension), they undergo hypertrophy (increased cell size) — not hyperplasia. Concentric LVH develops with sarcomere addition in parallel.<br><br>Take Notes: Hyperplasia → cell number increase (not in heart) | Metaplasia → tissue type change | Pressure overload heart = hypertrophy."},
/*152*/ {"q":"A 30-year-old man yawns and takes a deep breath. Which of the following muscles, when contracting to open the jaw widely, contributes most to changes in intrathoracic pressure that facilitate venous return to the heart?","o":["Lateral pterygoid","Medial pterygoid","Temporalis","Buccinator","Masseter"],"a":0,"e":"Lateral pterygoid is the principal jaw-opening muscle (depresses mandible and protracts it). During deep yawning, jaw opening accompanies deep inspiration which lowers intrathoracic pressure aiding venous return.<br><br>Take Notes: Medial pterygoid/temporalis/masseter → jaw closure | Buccinator → cheek | Jaw opening = lateral pterygoid."},
/*153*/ {"q":"A healthy 24-year-old man is seated quietly in a darkened room with eyes closed during an EEG recording. When asked to open his eyes and focus on a visual target, his EEG changes immediately. Which of the following best describes this transition?","o":["Beta waves to alpha waves","Alpha waves to beta waves","Theta waves to beta waves","Alpha waves to delta waves","Theta to Theta high frequency waves"],"a":1,"e":"EEG transitions: alpha waves (8-13 Hz) dominate when relaxed with eyes closed; switching to beta waves (>13 Hz) occurs immediately on eye opening or mental activity (\"alpha block\").<br><br>Take Notes: Delta → deep sleep | Theta → drowsy/light sleep | Alpha → relaxed eyes closed | Eye opening = alpha to beta."},
/*154*/ {"q":"A 26-year-old woman has normal glomerular filtration rate. Her urinalysis shows no glucose or amino acids in the urine. Which part of the nephron is primarily responsible for the complete reabsorption of these substances under normal physiological conditions?","o":["Proximal convoluted tubule","Loop of Henle","Distal convoluted tubule","Collecting duct","Thick limb of loop of Henle"],"a":0,"e":"PCT reabsorbs nearly 100% of filtered glucose and amino acids via secondary active transport (SGLT2 for glucose, various transporters for amino acids); these substances are not normally in urine.<br><br>Take Notes: Loop of Henle → water/NaCl | DCT → fine-tune sodium | Glucose/AA reabsorption = PCT (100%)."},
/*155*/ {"q":"A 49-year-old man with cirrhosis is admitted with hematemesis. Endoscopy reveals bleeding esophageal varices, which are treated with endoscopic band ligation. Which of the following medications should be given prophylactically to prevent recurrence of variceal bleeding?","o":["Propranolol","Atenolol","Amlodipine","Losartan","Proton Pump Inhibitors"],"a":0,"e":"Non-selective β-blockers (propranolol, nadolol) reduce portal pressure by decreasing cardiac output (β1) and producing splanchnic vasoconstriction (β2); reduce variceal rebleeding risk by ~50%.<br><br>Take Notes: Atenolol → cardioselective, not as effective | Selective β1 → no splanchnic effect | Variceal prophylaxis = propranolol."},
/*156*/ {"q":"A patient with symptomatic anemia receives one unit of packed red blood cells. Assuming no ongoing blood loss, by approximately how much will the hemoglobin concentration increase?","o":["0.5 g/dL","2.5 g/dL","1.5 g/dL","2 g/dL","1 g/dL"],"a":4,"e":"One unit of packed red blood cells typically raises hemoglobin by approximately 1 g/dL (hematocrit by ~3%) in a 70 kg adult, assuming no ongoing blood loss or hemolysis.<br><br>Take Notes: Pediatric patients → larger relative increase | Active bleeding → less rise per unit | 1 unit PRBCs = ~1 g/dL Hb increase."},
/*157*/ {"q":"A 62-year-old man presents with abdominal distension, vomiting, and absence of bowel movements for 3 days. Physical examination reveals high-pitched bowel sounds. The most appropriate initial imaging study for diagnosis is:","o":["Plain abdominal X-ray","CT scan of the abdomen with contrast","Ultrasound of the abdomen","MRI of the abdomen","ERCP"],"a":0,"e":"Suspected bowel obstruction: plain abdominal X-ray (erect and supine) is the appropriate initial imaging; shows dilated bowel loops, air-fluid levels (\"step-ladder\" appearance), and absence of distal gas. Quick and cheap.<br><br>Take Notes: CT → more sensitive (after X-ray) | USG → limited by gas | Bowel obstruction initial imaging = abdominal X-ray."},
/*158*/ {"q":"MHC class I presents with:","o":["CD 4","MHC class II","CD 8","CD 28","CD 16"],"a":2,"e":"MHC class I (on all nucleated cells) presents endogenous antigens to CD8+ cytotoxic T cells. MHC class II (on antigen-presenting cells) presents exogenous antigens to CD4+ helper T cells.<br><br>Take Notes: MHC I + CD8 → cytotoxic T cells | MHC II + CD4 → helper T cells | MHC I = CD8."},
/*159*/ {"q":"A 6-month-old infant presents with cough, wheezing, and difficulty breathing. Examination shows nasal flaring and subcostal retractions. PCR of nasopharyngeal secretions confirms the most common viral cause of bronchiolitis in infants. Which pathogen is most likely responsible?","o":["Influenza A virus","Parainfluenza virus","Respiratory syncytial virus","Adenovirus","Paramyxovirus"],"a":2,"e":"Respiratory syncytial virus (RSV) is the most common cause of bronchiolitis and lower respiratory tract infection in infants <2 years; causes wheezing, nasal flaring, retractions. Peak incidence in winter months.<br><br>Take Notes: Parainfluenza → croup | Adenovirus → various | Infant bronchiolitis = RSV."},
/*160*/ {"q":"A patient has a perforation found in the third part of the duodenum. Which structure is most likely to be invaded posteriorly?","o":["Abdominal aorta","Transverse mesocolon","Inferior vena cava","Head of pancreas","Lungs"],"a":0,"e":"Third part of duodenum (D3) crosses anterior to the abdominal aorta and inferior vena cava; posterior perforation can erode into the aorta causing catastrophic bleeding (aortoduodenal fistula).<br><br>Take Notes: Transverse mesocolon → anterior to D3 | Pancreas → adjacent (head) | D3 posterior perforation = aortic invasion."},
/*161*/ {"q":"A patient presents with jaundice. Laboratory tests show elevated ALT and AST with normal alkaline phosphatase. Which type of jaundice is most consistent with these findings?","o":["Prehepatic jaundice","Mixed pattern jaundice","Posthepatic jaundice","Hepatic jaundice","Hemolytic Jaundice"],"a":3,"e":"Hepatocellular (hepatic) jaundice: elevated transaminases (ALT/AST) with normal/mildly elevated ALP; caused by viral hepatitis, drug injury, autoimmune hepatitis. ALT > AST in viral; AST > ALT in alcoholic.<br><br>Take Notes: Posthepatic → ALP elevated (cholestasis) | Hemolytic → elevated unconjugated bilirubin | Elevated ALT/AST = hepatic jaundice."},
/*162*/ {"q":"A 57-year-old postmenopausal woman has been on prolonged estrogen therapy for menopausal symptoms. Which malignancy is she at increased risk of developing?","o":["Ovarian cancer","Endometrial cancer","Cervical cancer","Breast cancer","Liver cancer"],"a":1,"e":"Unopposed estrogen therapy in postmenopausal women dramatically increases endometrial cancer risk (10-fold); estrogen causes endometrial hyperplasia which can progress to carcinoma. Combined HRT (with progestin) reduces this risk.<br><br>Take Notes: Breast cancer → also increased risk with HRT | Combined estrogen + progestin → safer | Unopposed estrogen = endometrial cancer."},
/*163*/ {"q":"Most common congenital large vessel anomaly:","o":["ASD","VSD","PDA","TOF","Peripheral vascular disease"],"a":2,"e":"Patent ductus arteriosus (PDA) is the most common congenital large vessel anomaly. Failure of ductus arteriosus closure after birth maintains connection between aorta and pulmonary artery. More common in prematurity.<br><br>Take Notes: VSD → most common congenital heart defect overall | ASD → atrial septal | Large vessel anomaly = PDA."},
/*164*/ {"q":"A cytotoxic T lymphocyte recognizes a viral antigen presented on the surface of an infected cell. Which molecule is responsible for presenting this antigen?","o":["MHC class I","MHC class II","CD4","CD28","CD16"],"a":0,"e":"MHC class I (HLA-A, -B, -C) on all nucleated cells presents endogenous antigens (viral, tumor) to CD8+ cytotoxic T lymphocytes for cell killing. MHC class II presents exogenous antigens to CD4+ cells.<br><br>Take Notes: MHC II → CD4 helper T cells | CD28 → costimulation | Viral antigen presentation to CTL = MHC class I."},
/*165*/ {"q":"A patient develops high fever after prolonged exposure to high environmental temperatures while doing gardening. Which of the following drugs is most likely to have contributed to impaired thermoregulation and precipitated heat stroke?","o":["Clozapine","Amitriptyline","Buspirone","Risperidone","Diazepam"],"a":0,"e":"Clozapine and other antipsychotics with strong anticholinergic and dopamine-blocking effects impair thermoregulation; combined with hot environment, can precipitate heat stroke. Patients should avoid extreme heat.<br><br>Take Notes: Buspirone → minimal anticholinergic | Diazepam → not antipsychotic | Antipsychotic + heat = clozapine risk."},
/*166*/ {"q":"A 28-year-old pregnant woman perceives fetal movements at approximately 20 weeks of gestation. This sensation is most likely due to stretching of which of the following uterine ligaments?","o":["Round ligament","Broad ligament","Cardinal ligament","Suspensory ligament of ovary","Uterosacral ligament"],"a":0,"e":"Round ligament: extends from uterus to labia majora, passing through inguinal canal. Stretching of round ligament during pregnancy commonly causes sharp lower abdominal pain (round ligament pain).<br><br>Take Notes: Broad ligament → covering | Cardinal ligament → cervix to lateral pelvic wall | Pregnancy stretching = round ligament."},
/*167*/ {"q":"In which of the following conditions will both pulmonary systolic and diastolic pressures exceed alveolar air pressure throughout the cardiac cycle?","o":["Zone 1 of the lung","Zone 2 of the lung","Zone 3 of the lung","Pulmonary embolism","Massive pneumothorax"],"a":2,"e":"Zone 3 (lung base): both systolic and diastolic arterial pressures exceed alveolar pressure throughout cardiac cycle; flow is continuous and maximal. Gravity gives lower lung zones highest flow.<br><br>Take Notes: Zone 1 → alveolar > both | Zone 2 → systolic > alveolar > diastolic | Zone 3 = both > alveolar."},
/*168*/ {"q":"A 35-year-old man is brought to the emergency department after a motor vehicle collision. He is pale, diaphoretic, and complaining of shortness of breath. Blood pressure is 80/40 mmHg, pulse 140 bpm, respiratory rate 30/min. Which of the following is the most appropriate immediate step in management?","o":["Secure airway with endotracheal intubation","Establish two large bore intravenous lines and begin rapid fluid resuscitation","Arrange for emergency laparotomy","Begin intravenous vasopressors","Order CT scan"],"a":1,"e":"Hypovolemic shock (BP 80/40, tachycardia): ATLS \"C\" step — establish two large-bore IV lines, begin rapid fluid resuscitation (crystalloids, then blood). Airway often patent in awake patient.<br><br>Take Notes: Intubation → if airway compromised | Vasopressors → not first-line | Hypovolemia = 2 IVs + fluids."},
/*169*/ {"q":"A 55-year-old woman with known deep vein thrombosis presents with acute onset dyspnea and pleuritic chest pain. CT pulmonary angiography confirms a large pulmonary embolism. Which of the following is the most appropriate immediate initial management step?","o":["Thrombolytic therapy","Oxygen therapy","Anticoagulation with heparin","Surgical embolectomy","Inferior vena cava filter placement"],"a":1,"e":"Initial management of suspected/confirmed PE: oxygen therapy to maintain oxygenation, hemodynamic support, then anticoagulation. Thrombolysis if hemodynamic instability/massive PE. Embolectomy is last resort.<br><br>Take Notes: Anticoagulation → standard treatment after stabilization | Thrombolysis → unstable PE | Initial = oxygen therapy."},
/*170*/ {"q":"A 45-year-old man presents with sudden-onset inward deviation of the left eye and inability to abduct it. Imaging reveals a lesion in the cranial base. Damage to which of the following bony structures is most likely responsible?","o":["Greater wing of the sphenoid","Lesser wing of the sphenoid","Petrous part of temporal bone","Cribriform plate of the ethmoid","Body of sphenoid"],"a":2,"e":"Petrous temporal bone is closely related to abducens (CN VI) nerve as it passes over the petrous ridge through Dorello's canal; lesions cause abducens palsy with convergent squint.<br><br>Take Notes: Greater wing → V2, V3 | Lesser wing → CN II | CN VI + cranial base = petrous temporal."},
/*171*/ {"q":"Which of the following antacids or acid-reducing agents is a known inhibitor of cytochrome P450 enzymes?","o":["Omeprazole (PPI)","Cimetidine","Ranitidine","Magnesium hydroxide","Famotidine"],"a":1,"e":"Cimetidine (H2 receptor blocker) is a potent inhibitor of multiple CYP450 enzymes (1A2, 2C9, 2D6, 3A4); causes numerous drug interactions, increasing levels of warfarin, phenytoin, theophylline. Other H2 blockers (ranitidine, famotidine) lack this effect.<br><br>Take Notes: Omeprazole → mild CYP inhibition (2C19) | Antacids → no inhibition | P450 inhibitor antacid/H2 blocker = cimetidine."},
/*172*/ {"q":"A 42-year-old singer undergoes total thyroidectomy for multinodular goiter. Postoperatively, she has no difficulty speaking but cannot produce high-pitched sounds. Which nerve is most likely injured?","o":["External branch of superior laryngeal nerve","Internal branch of superior laryngeal nerve","Recurrent laryngeal nerve","Hypoglossal nerve","Vagus"],"a":0,"e":"External branch of superior laryngeal nerve (motor) supplies cricothyroid muscle (tenses vocal cords for high-pitch sounds); injured at superior thyroid artery ligation. Causes inability to produce high-pitched sounds (singer's nerve).<br><br>Take Notes: RLN injury → hoarseness | Internal SLN → sensory (cough) | High-pitched loss = external SLN."},
/*173*/ {"q":"A 60-year-old man presents with jaundice. CT scan reveals gallstones in the gallbladder and a stone lodged in the common bile duct. Which of the following laboratory findings would most specifically confirm obstruction of the biliary tract?","o":["Elevated ALT and AST","Elevated alkaline phosphatase","Elevated amylase","Elevated bilirubin with normal ALP","Elevated transaminases only"],"a":1,"e":"Biliary obstruction: alkaline phosphatase (and GGT) elevation is most specific finding; reflects biliary epithelium damage. ALT/AST may rise mildly. Bilirubin (conjugated) rises with prolonged obstruction.<br><br>Take Notes: ALT/AST → hepatocellular | Amylase → pancreatic | Biliary obstruction specific marker = elevated ALP."},
/*174*/ {"q":"A 23-year-old woman presents with a painless, firm, mobile breast mass with well-defined borders. There is no nipple discharge or skin dimpling. Which of the following is the most likely diagnosis?","o":["Fibroadenoma","Fibrocystic change","Invasive ductal carcinoma","Intraductal papilloma","Breast cyst"],"a":0,"e":"Fibroadenoma: most common breast tumor in young women (<30 years); painless, firm, mobile, well-circumscribed (\"breast mouse\"). Benign; estrogen-sensitive. Usually managed conservatively or excised if symptomatic.<br><br>Take Notes: Cyst → fluctuant | Carcinoma → fixed, irregular | Young woman + mobile firm well-defined = fibroadenoma."},
/*175*/ {"q":"A 74-year-old man presents with back pain and urinary hesitancy. Digital rectal exam reveals a hard, irregular prostate with loss of the median sulcus. PSA is markedly elevated. Bone scan shows sclerotic lesions in the vertebrae. Most likely diagnosis?","o":["Benign prostatic hyperplasia","Prostate cancer","Chronic prostatitis","Urethral stricture","Pelvic abscess"],"a":1,"e":"Prostate adenocarcinoma: PSA markedly elevated, hard irregular nodular prostate, loss of median sulcus, and bone metastases (typically osteoblastic/sclerotic, lumbar/pelvic). Bone scan shows sclerotic lesions.<br><br>Take Notes: BPH → smooth, soft, no bone mets | Prostatitis → tender, fever | Hard nodular prostate + sclerotic bone mets = prostate cancer."},
/*176*/ {"q":"The epithelium lining the fallopian tube is best described as:","o":["Simple cuboidal epithelium","Simple columnar epithelium ciliated","Stratified squamous non-keratinized epithelium","Transitional epithelium","Pseudostratified columnar"],"a":1,"e":"Fallopian tube epithelium is simple columnar ciliated with secretory peg cells; cilia transport ovum toward uterus. Ciliated cells beat in coordinated direction; estrogen-dependent.<br><br>Take Notes: Cervix → simple columnar | Vagina → stratified squamous | Fallopian tube = simple columnar ciliated."},
/*177*/ {"q":"A 16-year-old girl presents with fever, polyarthritis, and a recent history of sore throat. She is suspected of having acute rheumatic fever. Which of the following medications, if prescribed, would confirm the diagnosis as per a therapeutic trial?","o":["Aspirin","Prednisone","High-dose penicillin","Naproxen","Methotrexate"],"a":0,"e":"Therapeutic trial of aspirin (salicylates) causes rapid dramatic relief of joint symptoms in acute rheumatic fever (within 24-48 hours); this rapid response supports the diagnosis. Salicylate is treatment of arthritis component.<br><br>Take Notes: Penicillin → treats strep, not symptoms | Naproxen → less specific | Rheumatic fever therapeutic trial = aspirin."},
/*178*/ {"q":"A patient presents with elevated bilirubin levels but normal ALT, AST, and GGT. Which of the following is the most likely cause?","o":["Prehepatic jaundice (hemolytic)","Hepatic jaundice","Posthepatic jaundice","Obstructive jaundice","Drug-induced hepatitis"],"a":0,"e":"Prehepatic (hemolytic) jaundice: elevated unconjugated bilirubin from increased RBC destruction; ALT, AST, GGT, ALP all normal as liver and biliary tree are not affected. Examples: hemolytic anemia, Gilbert syndrome.<br><br>Take Notes: Hepatic → ALT/AST elevated | Posthepatic → ALP/GGT elevated | Isolated bilirubin rise = prehepatic (hemolytic)."},
/*179*/ {"q":"A 64-year-old man presents with crushing substernal chest pain for 5 hours. Troponin I is elevated. Autopsy later shows preservation of tissue architecture but loss of nuclei and increased eosinophilia of the cytoplasm. Which type of necrosis is most likely?","o":["Coagulative necrosis","Liquefactive necrosis","Fat necrosis","Caseous necrosis","Fibrinoid necrosis"],"a":0,"e":"Myocardial infarction characteristically shows coagulative necrosis: tissue architecture preserved (ghost outlines), loss of cellular detail (anucleate, eosinophilic cytoplasm). Most common in heart, kidney, spleen.<br><br>Take Notes: Liquefactive → brain, abscess | Caseous → TB | MI necrosis type = coagulative."},
/*180*/ {"q":"A newborn presents with delayed passage of meconium, abdominal distension, and bilious vomiting. Which of the following is the gold standard for definitive diagnosis?","o":["CT scan","MRI","Barium enema","Rectal biopsy (Hirschsprung disease)","Anorectal manometry"],"a":3,"e":"Hirschsprung disease (congenital aganglionic megacolon): delayed meconium, distension, bilious vomiting. Rectal suction biopsy is the gold standard — demonstrates absence of ganglion cells in submucosal and myenteric plexuses.<br><br>Take Notes: Barium enema → transition zone shown | Anorectal manometry → screening | Definitive Hirschsprung = rectal biopsy."},
/*181*/ {"q":"A 45-year-old man presents with sudden-onset shortness of breath and chest pain after prolonged immobilization. CT angiography confirms pulmonary embolism. Which of the following findings would most likely be seen in a fat embolism rather than a thrombotic pulmonary embolism?","o":["Elevated D-dimer","Petechial rash","Right heart strain on echocardiography","Elevated troponin","Pleural effusion"],"a":1,"e":"Fat embolism syndrome (classically 24-72 hours after long bone fracture): triad of respiratory distress, neurological abnormalities, and petechial rash (axilla, neck, chest, conjunctiva). Distinguishes from thromboembolic PE.<br><br>Take Notes: D-dimer/RH strain → both PE types | Troponin → both possible | Petechial rash = fat embolism (not thrombotic)."},
/*182*/ {"q":"A 32-year-old woman has been using combined oral contraceptive pills for 12 years. Which of the following is a known possible complication of long-term use?","o":["Breast carcinoma","Endometrial carcinoma","Hepatic adenoma","Ovarian carcinoma","Pancreatic cancer"],"a":2,"e":"Hepatic adenoma: benign liver tumor associated with prolonged OCP use; rare but known complication. Other risks: venous thromboembolism, hypertension. OCPs actually reduce ovarian and endometrial cancer risk.<br><br>Take Notes: OCPs → reduce ovarian/endometrial cancer | Slight breast cancer increase | OCP-associated tumor = hepatic adenoma."},
/*183*/ {"q":"A 45-year-old woman develops jaundice and markedly elevated liver enzymes two weeks after starting antibiotic therapy for a urinary tract infection. Which of the following drugs is most likely responsible for this reaction?","o":["Ampicillin","Ciprofloxacin","Penicillin G","Erythromycin","Doxycycline"],"a":3,"e":"Erythromycin (macrolide) causes cholestatic hepatitis with jaundice, typically 2-4 weeks after starting therapy; erythromycin estolate has highest risk. Reversible after discontinuation. Mechanism: hepatocyte injury and cholestasis.<br><br>Take Notes: Ampicillin → rash | Cipro → tendon rupture | Drug-induced cholestatic jaundice = erythromycin."},
/*184*/ {"q":"A 6-year-old child presents with low-grade fever, sore throat, and a thick gray-white membrane over the pharynx. Which of the following organisms is the most likely cause?","o":["Streptococcus pyogenes","Corynebacterium diphtheriae","Haemophilus influenzae","Epstein-Barr virus","Bordetella pertussis"],"a":1,"e":"Diphtheria (Corynebacterium diphtheriae): characteristic pseudomembrane (thick gray-white, adherent) on tonsils and pharynx; toxin causes systemic effects (myocarditis, neuropathy). Treated with antitoxin and erythromycin.<br><br>Take Notes: S. pyogenes → red erythematous pharynx, no membrane | EBV → pharyngitis + splenomegaly | Pharyngeal membrane = diphtheria."},
/*185*/ {"q":"Which structure lies anterior to the pancreas?","o":["Superior mesenteric vein","Inferior mesenteric vein","Sigmoid colon","Transverse mesocolon","Kidney"],"a":3,"e":"Transverse mesocolon attaches anteriorly to the pancreas (along its anterior border) and divides the abdominal cavity into supracolic and infracolic compartments. SMV passes posterior to pancreatic neck.<br><br>Take Notes: SMV/SMA → posterior to neck of pancreas | Kidney → posterior | Anterior to pancreas = transverse mesocolon."},
/*186*/ {"q":"A 14-year-old boy presents with fever, headache, and neck stiffness. CSF analysis shows lymphocytic predominance, normal glucose, and mildly elevated protein. Which of the following is the most likely diagnosis?","o":["Bacterial meningitis","Viral meningitis","Tuberculous meningitis","Fungal meningitis","Cryptococcal meningitis"],"a":1,"e":"Viral (aseptic) meningitis: lymphocytic pleocytosis, normal glucose, mildly elevated protein. Common causes: enteroviruses, mumps, HSV. Self-limiting, supportive care.<br><br>Take Notes: Bacterial → neutrophils + low glucose + high protein | TB → very low glucose + lymphocytes | Lymphocytes + normal glucose = viral."},
/*187*/ {"q":"A patient develops perioral tingling, muscle cramps, and positive Chvostek and Trousseau signs after total thyroidectomy. Which electrolyte abnormality is most likely?","o":["Hypocalcemia","Hypokalemia","Hyponatremia","Hypochloremia","Hypomagnesemia"],"a":0,"e":"Post-thyroidectomy hypocalcemia (from parathyroid damage/removal): perioral tingling, paresthesias, muscle cramps, positive Chvostek (facial twitch) and Trousseau signs (carpopedal spasm with BP cuff). Treat with IV calcium.<br><br>Take Notes: Hypomagnesemia → similar features but no thyroid history | Hypokalemia → muscle weakness | Post-thyroidectomy tetany = hypocalcemia."},
/*188*/ {"q":"Which of the following cephalosporins is considered safe for use in patients with chronic kidney disease due to predominant biliary excretion?","o":["Cefixime","Cefotaxime","Cefoperazone","Ceftriaxone","Cefuroxime"],"a":3,"e":"Ceftriaxone has dual excretion (60% renal, 40% biliary); no dose adjustment usually needed in renal impairment. Cefoperazone is also primarily biliary excreted but less preferred clinically.<br><br>Take Notes: Other cephalosporins → renal clearance, need dose adjustment | Renal-friendly cephalosporin = ceftriaxone (dual excretion)."},
/*189*/ {"q":"A 12-year-old boy presents with progressive bilateral sensorineural hearing loss and episodes of painless hematuria since childhood. His father had similar symptoms and developed renal failure in his 30s. Fundoscopic examination reveals anterior lenticonus. Which of the following is the most likely diagnosis?","o":["Goodpasture syndrome","Alport syndrome","IgA nephropathy","Membranoproliferative glomerulonephritis","Wegener granulomatosis"],"a":1,"e":"Alport syndrome: X-linked (mostly) type IV collagen defect; triad of hereditary nephritis (hematuria → CKD), sensorineural hearing loss, and ocular abnormalities (anterior lenticonus). Defects in COL4A3/4/5 genes.<br><br>Take Notes: Goodpasture → anti-GBM antibodies | IgA nephropathy → no hearing loss | Hereditary nephritis + deafness + lenticonus = Alport."},
/*190*/ {"q":"A 6-year-old child receives a therapeutic injection containing diphtheria toxin as part of a research-based treatment protocol. Within minutes, he develops widespread urticaria, dyspnea, and intense itching. Which type of hypersensitivity reaction is most likely responsible?","o":["Type I","Type II","Type III","Type IV","Type V"],"a":0,"e":"Anaphylaxis (within minutes of exposure): Type I hypersensitivity, IgE-mediated mast cell degranulation releasing histamine, leukotrienes, tryptase. Causes urticaria, bronchospasm, angioedema, and shock.<br><br>Take Notes: Type II → antibody-mediated cell damage | Type III → immune complex | Anaphylaxis = type I (IgE-mediated)."},
/*191*/ {"q":"An infection originating in the pretracheal space is most likely to spread directly into which of the following compartments?","o":["Anterior mediastinum","Superior mediastinum","Posterior mediastinum","Carotid sheath","Pleural cavity"],"a":0,"e":"Pretracheal space (between visceral and parietal layers of pretracheal fascia) is continuous inferiorly with the anterior mediastinum; infection spreads downward into the anterior mediastinum causing mediastinitis (descending necrotizing mediastinitis).<br><br>Take Notes: Retropharyngeal → posterior mediastinum (via danger space) | Carotid sheath → separate fascial compartment | Pretracheal infection = anterior mediastinum."},
/*192*/ {"q":"During axillary lymph node dissection for breast carcinoma, a surgeon accidentally injures a nerve traveling with the lateral thoracic artery. Postoperatively, the patient has difficulty raising her arm above her head and exhibits winging of the scapula. Which nerve was injured?","o":["Long thoracic nerve","Thoracodorsal nerve","Spinal accessory nerve","Suprascapular nerve","Axillary nerve"],"a":0,"e":"Long thoracic nerve supplies serratus anterior muscle (protracts scapula and stabilises medial border); injury during axillary surgery causes winging of scapula and inability to raise arm above head.<br><br>Take Notes: Spinal accessory → trapezius (also winging but lateral) | Thoracodorsal → latissimus dorsi | Serratus anterior winging = long thoracic nerve."},
/*193*/ {"q":"A 64-year-old man develops deep vein thrombosis and is started on warfarin therapy. Which of the following best describes warfarin's mechanism of action?","o":["Inhibits gamma-glutamyl carboxylase","Inhibits platelet aggregation","Inhibits thromboxane A2 synthesis","Activates antithrombin III","Inhibits factor Xa directly"],"a":0,"e":"Warfarin inhibits vitamin K epoxide reductase, preventing reduction of vitamin K to its active form; this impairs gamma-glutamyl carboxylase function and synthesis of functional clotting factors II, VII, IX, X, and proteins C/S.<br><br>Take Notes: Aspirin → COX inhibition (thromboxane) | Heparin → antithrombin III | Warfarin = blocks vitamin K → gamma-carboxylation."},
/*194*/ {"q":"A 40-year-old construction worker presents with progressive hearing loss in both ears. He reports working in a noisy environment for the past 20 years without hearing protection. Chronic exposure to loud noise most likely damages which of the following inner ear structures?","o":["Organ of Corti","Outer hair cells","Tympanic membrane","Auditory nerve","Stapes"],"a":1,"e":"Noise-induced sensorineural hearing loss: outer hair cells (basal turn of cochlea, high-frequency region) are particularly vulnerable to chronic noise exposure; loss causes high-frequency hearing loss (4 kHz notch on audiometry).<br><br>Take Notes: Inner hair cells → also affected later | TM → conductive loss | Noise damage = outer hair cells (basal)."},
/*195*/ {"q":"A patient with Sheehan syndrome presents with dizziness, fatigue, and tiredness. Which hormone is primarily responsible for these symptoms?","o":["TSH","GnRH","Cortisol","ACTH","Prolactin"],"a":3,"e":"Sheehan syndrome (postpartum pituitary necrosis): ACTH deficiency causes secondary adrenal insufficiency and cortisol deficiency, producing fatigue, dizziness, hypotension. Most immediately life-threatening hormonal deficiency.<br><br>Take Notes: TSH loss → slow myxedema | GnRH loss → amenorrhea | Sheehan acute dizziness/fatigue = ACTH deficiency."},
/*196*/ {"q":"After prolonged dehydration, a patient is found to have very concentrated urine. At which site in the nephron would the tubular fluid be most hypotonic?","o":["Early distal convoluted tubule","Proximal convoluted tubule","Cortical collecting tubule","Loop of Henle","Thick ascending limb"],"a":3,"e":"Thick ascending limb actively reabsorbs Na+/K+/2Cl- without water (water-impermeable), creating the most hypotonic fluid in the nephron — the \"diluting segment.\"<br><br>Take Notes: PCT → isotonic | CD → ADH-controlled | Most hypotonic = thick ascending limb (TAL)."},
/*197*/ {"q":"A 6-month-old infant presents with cough, wheezing, and difficulty breathing. Examination shows nasal flaring and subcostal retractions. PCR of nasopharyngeal secretions confirms the most common viral cause of bronchiolitis in infants. Which pathogen is most likely responsible?","o":["Influenza A virus","Parainfluenza virus","Respiratory syncytial virus","Adenovirus","Coronavirus"],"a":2,"e":"Respiratory syncytial virus (RSV) is the most common cause of bronchiolitis in infants <2 years; presents with cough, wheezing, nasal flaring, retractions. Peak incidence November-March. Confirmed by nasal PCR or rapid antigen.<br><br>Take Notes: Parainfluenza → croup (laryngotracheobronchitis) | Adenovirus → various respiratory | Infant bronchiolitis = RSV."},
/*198*/ {"q":"A 52-year-old man has the following fasting laboratory results: Total cholesterol 180 mg/dL, LDL cholesterol 25 mg/dL, Triglycerides 200 mg/dL, Fasting plasma glucose 134 mg/dL. Which of the following hormones is most likely responsible for this lipid and glucose pattern?","o":["Estrogen","Progesterone","Corticosteroids","Luteinizing hormone","Follicle stimulating hormone"],"a":2,"e":"Corticosteroid (cortisol/glucocorticoid) excess: causes insulin resistance, hyperglycemia, and dyslipidemia (increased triglycerides). Endogenous (Cushing) or exogenous steroids produce this metabolic profile.<br><br>Take Notes: Estrogen → variable lipid effects | LH/FSH → reproductive | Hyperglycemia + dyslipidemia = corticosteroid effect."},
];
